const typeName=x=>({repository:t('Code repository','代码仓库'),dataset:t('Dataset','数据集'),benchmark:t('Benchmark / environment','基准 / 评测环境'),model:t('Model / weights','模型 / 权重'),artifact:t('Research archive','研究归档'),project_page:t('Project / documentation','项目 / 文档')})[x]||x;
