const FORM_SHADE=[100,78,60,46,34,24];const formsList=()=>taxonomy?.forms||[];const formOf=p=>taxonomy?.paperForms?.[p.id];
function formBar(ps,w){const fs=formsList(),c=fs.map(f=>ps.filter(p=>formOf(p)===f.id).length),tot=c.reduce((a,b)=>a+b,0);if(!tot)return '';return `<span class="ftrack" aria-hidden="true"><span class="fbar" style="width:${w}%">${fs.map((f,i)=>c[i]?`<i style="flex:${c[i]};background:color-mix(in srgb,var(--cat) ${FORM_SHADE[i]}%,#fff)"></i>`:'').join('')}</span></span>`}
const formTitle=ps=>formsList().map(f=>`${translated(f.en)} ${ps.filter(p=>formOf(p)===f.id).length}`).join(' · ');
