function searchText(p){const key=state.lang+'|'+p.id;if(!searchCache.has(key))searchCache.set(key,[p.title,p.summary,translated(p.summary),p.scope,...p.authors,p.venue,p.venueReported,...(p.searchAliases||[]),...p.tags,...p.tags.map(translated),...topicsOf(p).map(topicName),...p.teams.map(id=>teamById.get(id)?.name)].join(' ').toLowerCase());return searchCache.get(key)}
// every word may appear anywhere and in any order; "a quoted phrase" is matched as written
const queryTerms=q=>/^".+"$/.test(q)?[q.slice(1,-1)]:q.split(/\s+/).filter(Boolean);
function filtered(skipTopic=false){const q=state.query.trim().toLowerCase();return data.papers.filter(p=>{
 const v=p.publication;
 return (state.pending?p.status!=='out_of_scope':p.status==='included')&&(!state.year||yearOf(p)===state.year)&&(skipTopic||!state.tag||(taxonomy?topicsOf(p).includes(state.tag):p.tags.includes(state.tag)))&&(skipTopic||!state.cat||topicsOf(p).some(x=>topicInfo(x)?.category===state.cat))&&(!state.team||p.teams.includes(state.team))&&(!state.venue||v.venueId===state.venue)&&(!state.group||famOf(p)===state.group)&&(!state.form||formOf(p)===state.form)&&(!state.rel||p.attributes?.curation_release===state.rel)&&(!state.facet||facetMatch(p.id,state.facet))&&(!state.country||countriesOf(p).has(state.country))&&(!state.art||(state.art==='code'?hasCode(p):p.resources.length>0))&&(!state.track||v.track===state.track)&&(!state.publication||v.status===state.publication)&&(!q||queryTerms(q).every(w=>searchText(p).includes(w)));
})}
function countTopics(papers=included()){const result={};for(const p of papers)for(const x of (taxonomy?topicsOf(p):p.tags))result[x]=(result[x]||0)+1;return result}
const chip=s=>`<span class="tag">${escape(s)}</span>`;
