function extraTags(p){const ts=topicsOf(p).map(tagWords);return p.tags.filter(x=>{const w=[...tagWords(x)];return !w.length||!ts.some(tw=>w.every(v=>tw.has(v)))})}
const topicChip=x=>`<button class="tag topic-tag" data-tag="${escape(x)}" style="--cat:${topicColor(x)}" title="${escape(t('Filter by this topic','按此主题筛选'))}">${escape(topicName(x))}</button>`;
