function paperRow(p){return `<article class="paper"><div class="paper-meta"><span class="year">${escape(yearOf(p)||t('Unknown year','年份未知'))}</span><span>${escape(pubName(p))}</span>${p.status!=='included'?chip(t('Pending scope review','范围待复核')):''}${p.attributes?.withdrawal?`<span class="tag withdrawn">${t('Withdrawn on arXiv','已在 arXiv 撤回')}</span>`:''}</div><button class="paper-title" data-paper="${escape(p.id)}">${escape(p.title)}</button><div id="abstract-${escape(p.id)}" class="summary paper-summary${expandedAbstracts.has(p.id)?' is-expanded':''}">${text(p,'summary')}<button class="summary-toggle" data-abstract="${escape(p.id)}" aria-controls="abstract-${escape(p.id)}" aria-expanded="${expandedAbstracts.has(p.id)}" hidden>${expandedAbstracts.has(p.id)?t('Less','收起'):t('More','展开')}</button></div><div class="tags">${topicsOf(p).map(topicChip).join('')}${extraTags(p).map(x=>chip(translated(x))).join('')}</div><div class="rowfoot"><span>${escape(p.authors.slice(0,2).join(' · '))}${p.authors.length>2?` · ${p.authors.length} ${t('authors','位作者')}`:''}</span><button data-paper="${escape(p.id)}">${p.resources.length?`${p.resources.length} ${t('resources','项资源')} · `:''}${t('View details','查看详情')} ↗</button></div></article>`}
function primaryNavigation(labels){
 const current=id=>state.view===id||(id==='resources'&&state.view==='oss')||(id==='discover'&&state.view==='findings');
 const primary=[homeView(),...(taxonomy?['explore','landscape','papers','resources']:['resources'])];
 // the three research layers (owner, 2026-10-19): 观察 (1) › 追问 (2) › 发现 (3), set apart from the entry views (宇宙·路径·探索台) and the catalogues
 const layer={},lname=k=>[t('Layer 1 · explore and observe','第一层 · 探索与观察'),t('Layer 2 · question and test','第二层 · 追问与检验'),t('Layer 3 · synthesise','第三层 · 综合发现')][k-1];
 const between=(a,b)=>!a?'':layer[a]&&layer[b]?(layer[a]!==layer[b]?'<span class="site-nav-step" aria-hidden="true">›</span>':''):(layer[a]||layer[b])?'<span class="site-nav-sep" aria-hidden="true"></span>':'';
 const groups=[
  {label:t('Method & data','方法与数据'),ids:['method']}
 ];
 const item=(id,extra='')=>`<button data-view="${id}" class="${extra}${layer[id]?` site-nav-l${layer[id]}`:''}${current(id)?' active':''}" ${current(id)?'aria-current="page"':''}${layer[id]?` title="${lname(layer[id])}"`:''}>${labels[id]}</button>`;
 const FINDINGS=['evolution','foundations','opportunities','evidence'],FIND=[['evolution',t('Research evolution','研究演化'),t('How the structure of the field formed and changed','领域结构怎样形成与变化')],['foundations',t('Foundations & protection','基础与保护'),t('What new work builds on, and what protection trusts','新研究建立在什么上，保护依赖什么')],['opportunities',t('Opportunities & tests','机会与检验'),t('Where to test next, and one test done','下一步该检验哪里，以及一项已完成的检验')],['evidence',t('Checks','核查'),t('How the platform checks itself','平台怎样核查自己')]],OBS=[['key',t('Featured','精选观察'),t('The strongest observations on one page','一页看最重要的观察')],['guide',t('Guide','导读'),t('How each part counts','各部分怎么计数')],['structure',t('Positioning','定位'),t('What papers study: agents and safety','论文研究什么：智能体与安全')],['connect',t('Connection','衔接'),t('How research lines connect','研究方向之间怎样衔接')],['lead',t('Countries & institutions','国家与机构'),t('Where the work comes from; who drives it','研究来自哪里，谁在推动')],['evolve',t('Trajectory','走向'),t('How the head and the long tail change','头部与长尾怎样变化')],['models',t('Models','模型'),t('Which models 2026 papers work with','2026 年论文在用哪些模型')],['oss',t('Open source','开源'),t('Repositories against the papers','开源仓库与论文对照')]],inMore=groups.some(g=>g.ids.some(current));
 return `<nav class="site-nav" aria-label="${t('Main navigation','主导航')}"><div class="site-nav-items">
 ${primary.slice(0,3).map((id,i)=>item(id,i?'site-nav-research':'site-nav-home')).join('')}<details class="site-nav-more site-nav-findings site-nav-disc${FINDINGS.some(current)||current('discover')?' active':''}"><summary>${t('Findings','发现')}<span class="site-nav-chevron" aria-hidden="true">⌄</span></summary><div class="site-nav-panel"><div class="site-nav-mega"><div class="site-nav-group"><span class="site-nav-gl">${t('Conclusions','研究结论')}</span>${FIND.map(([id,n,d])=>`<button data-view="${id}" ${current(id)?'aria-current="page"':''}><b>${n}</b><small>${d}</small></button>`).join('')}</div><div class="site-nav-group"><span class="site-nav-gl">${t('Observations from the data','数据观察')}</span><div class="site-nav-two">${OBS.map(([k,n,d])=>{const on=current('discover')&&(state.lens||'key')===k;return `<a href="#discover?lens=${k}" ${on?'aria-current="page"':''}><b>${n}</b><small>${d}</small></a>`}).join('')}</div></div></div></div></details>${primary.slice(3).map(id=>item(id,'site-nav-research')).join('')}
 <details class="site-nav-more${inMore?' active':''}"><summary aria-label="${t('More: method, data and versions','更多：方法、数据与版本')}">${t('More','更多')}<span class="site-nav-chevron" aria-hidden="true">⌄</span></summary>
 <div class="site-nav-panel">${groups.map(g=>`<div class="site-nav-group"><span class="site-nav-heading">${g.label}</span>${g.ids.map(id=>item(id)).join('')}</div>`).join('')}</div></details>
 </div></nav>`;
}
function updateNavigation(revealActive=false){
 const nav=document.querySelector('.site-nav'),strip=nav?.querySelector('.site-nav-items');if(!strip)return;
 if(revealActive&&matchMedia('(max-width:760px)').matches){
  const active=strip.querySelector(':scope>button.active,:scope>details.active');
  if(active){const r=active.getBoundingClientRect(),box=strip.getBoundingClientRect();if(r.right>box.right-16)strip.scrollLeft+=r.right-box.right+16;else if(r.left<box.left+16)strip.scrollLeft+=r.left-box.left-16;}
 }
 nav.classList.toggle('has-scroll-start',strip.scrollLeft>1);
 nav.classList.toggle('has-scroll-end',strip.scrollLeft+strip.clientWidth<strip.scrollWidth-1);
}
function initNavigation(){document.querySelector('.site-nav-items')?.addEventListener('scroll',()=>updateNavigation(),{passive:true});updateNavigation(true);}
function closeNavigation(restoreFocus=false){const menu=document.querySelector('.site-nav-more[open]');if(menu){menu.open=false;if(restoreFocus)menu.querySelector('summary').focus();}}
document.addEventListener('click',e=>{if(!e.target.closest('.site-nav-more')||e.target.closest('.site-nav-panel a,.site-nav-panel button'))closeNavigation();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.querySelector('.site-nav-more[open]')){e.preventDefault();closeNavigation(true);}});
document.addEventListener('focusin',e=>{if(!e.target.closest('.site-nav-more'))closeNavigation();});

// the research layer of a page, named beside its title (owner, 2026-10-19: no wide bar, just say which layer it is)
function layerTag(v){const k={}[v];if(!k)return '';const n=[t('observe','观察'),t('question and test','追问与检验'),t('synthesise','综合发现')],q=[t('Within what data, what do we see?','在什么数据范围内，看到了什么？'),t('Under what conditions does it hold, and what follows?','这个现象在什么条件下成立，我们能推出什么？'),t('Together, what do these results change in how we see the field?','这些结果合起来，改变了我们对领域的什么理解？')];return `<span class="layer-tag" title="${q[k-1]}"><span class="layer-dots" aria-hidden="true">${[1,2,3].map(i=>`<i class="${i===k?'on':i<k?'done':''}"></i>`).join('')}</span>${t(`Layer ${k} of 3 · ${n[k-1]}`,`第${'一二三'[k-1]}层 · ${n[k-1]}`)}</span>`}
function shell(){const labels=views(),groups=groupNames();document.documentElement.lang=state.lang==='zh'?'zh-CN':'en';document.title='Agent Safety Atlas';$('#app').innerHTML=`
<header class="site-header"><a href="#${homeView()}" class="brand" data-view="${homeView()}" aria-label="Agent Safety Atlas"><span class="xmark" aria-hidden="true"><svg viewBox="0 0 40 40"><rect x="1" y="1" width="38" height="38" rx="11"/><g class="xstrokes"><path d="M11 27 18 14 28 20 26 30" style="stroke-width:2"/><circle cx="11" cy="27" r="2.6"/><circle cx="18" cy="14" r="2.6"/><circle cx="28" cy="20" r="3.4"/><circle cx="26" cy="30" r="2.2"/></g></svg></span><span class="brand-title">Agent Safety Atlas<small>${t('RESEARCH & OPEN RESOURCES','研究与开放资源')}</small></span></a>${primaryNavigation(labels)}<div class="header-tools"><button class="theme-switch" id="theme" aria-label="${t('Switch light or dark','切换浅色或深色')}" title="${t('Switch light or dark','切换浅色或深色')}">${document.documentElement.dataset.theme==='light'?'☾':'☀'}</button><button class="language-switch" id="language" aria-label="${t('Switch to Chinese','Switch to English')}">${t('中文','English')}</button></div></header>
<main class="view-${state.view}"><div class="pagehead"><div><div class="eyebrow">AGENT SAFETY / ${t('RESEARCH INDEX','研究索引')}</div><h1>${labels[state.view]}${layerTag(state.view)}</h1><p class="muted">${({timemap:t('Where agent-safety work comes from, month by month. Drag the time slider or press play, filter by cluster or role, and open any institution’s papers; each insight on the right sets the map to the view that shows it.','Agent 安全研究从哪里来，逐月变化。拖动时间条或点击播放，按星团或角色筛选，点开任一机构的论文；右侧每条洞察点击后会把地图调到对应配置。'),landscape:t('Agent-safety research at a glance: where it comes from, where it happens and how it is distributed. Click a chart element to open the matching papers. These views cover all 5,782 works of the collection, including the 404 first published after the field cutoff; field statistics use the 5,378 works of the frozen map.','一览 Agent 安全研究：数据从哪里来、研究在哪里发生、如何分布。点击图表中的元素即可打开对应论文。'),papers:t('The works every number on this site is computed from. Search, or filter by theme and cluster, year, venue, paper form or contribution role; open a work for its versions, evidence and resources.','本站所有数字的来源。可以搜索，或按主题与星团、年份、会议、论文形式、贡献角色筛选；点开论文查看其版本、证据与资源。'),explore:t('Explore an idea through research directions, papers and resources.','从想法出发，探索研究方向、论文与配套资料。'),topics:t('Understand each field, explore its evidence and follow a reading route.','理解每个领域，探索数据证据，建立论文阅读路线。'),research:t('Connect safety questions with research, resources and teams.','连接安全问题、研究成果、开放资源与研究团队。'),resources:t('Code, datasets, models and project pages released with included papers, organized by paper.','纳入论文配套发布的代码、数据集、模型与项目页，按论文组织。'),teams:t('Explore institutions through paper affiliations and primary evidence.','依据论文署名与原始证据探索研究机构。'),insights:t('Explore research signals, contribution indices and evidence.','探索研究信号、贡献指数及其证据。'),snapshot:t('The package behind the paper: works, typed relations with their basis, clusters, institutions and the observation report for one release, with checksums and recompute steps.','论文背后的资源包：某一版本的工作、带出处的类型化关系、星团、机构与观测报告，附校验和与复算步骤。'),home:'',discover:t('What the data shows, computed on the frozen field map (5,378 works, 14 themes, 61 clusters). Four parts are about the papers (positioning, connection, countries and institutions, trajectory); two boards cover the models papers use and the open-source side. Open any answer for its evidence and the papers behind it.','数据里看到了什么，基于冻结领域地图（5,378 篇论文、14 个主题、61 个星团）计算。前四部分关于论文（定位、衔接、国家与机构、走向），另两块分别关于论文用的模型和开源仓库。点开任一回答，可看到证据和背后的论文。'),questions:t('Four research questions (problem coverage, strength of evidence, connections across directions, the life cycle of contributions), each split into sub-questions with a card of its own; the earlier questions sit under the sub-question they serve.','四个研究问题（问题覆盖、证据强度、方向间联系、贡献的生命周期），每个拆成若干子问题，各有一张卡；原有的追问归入它们服务的子问题之下。'),rq:t('The paper\'s research questions, worked through on the data: the evolution film, the field over time, checked cases and what could not be identified early. Preview only.','论文研究问题在数据上的完整过程：星团演化片、领域格局变化、经过核对的案例，以及尚不能提前识别的部分。仅在预览站。'),
synthesis:t('What accumulates as agent-safety research grows? One answer per research question, the sub-questions each rests on, and the earlier findings.','随着 Agent 安全研究的增长，究竟积累了什么？每个研究问题一个回答、它依据的子问题，以及早先的发现。'),notes:t('Smaller observations: true, sometimes useful, too small for a lens of their own.','小观察：真实、有时有用，但不足以单独成为一个视角。'),method:t('How the figures are made: what was observed, the four fractures, hypotheses, Web relevance, routes and the benchmark-use audit.','这些数字怎样得到：观测范围、四种断裂、假设状态、Web 相关性、航线与基准采用抽查。'),findings:t('What the data shows, in four parts about the papers and two boards on models and open source; the observations worth probing become Questions.','数据里看到了什么：前四部分关于论文，另两块关于模型和开源；值得深究的观察在“追问”里变成研究问题。'),analysis:t('How agent-safety research is distributed over time, themes, paper forms and publication venues.','Agent 安全研究在时间、主题、论文形式与发表来源上的分布。'),coverage:t('Where the data comes from: sources scanned, how candidates were screened and verified, and known gaps.','数据从哪里来：扫描了哪些来源、候选如何筛选与核验，以及已知缺口。'),updates:t('Every update of the Atlas: what was added, verified or flagged, with the totals after each release. Updates run automatically every Monday and Thursday.','图谱的每一次更新：新增、核实与标注了什么，以及每次发布后的总量。每周一和周四自动更新。'),oss:t('GitHub repositories on agent security: tools, research implementations (including every included paper’s own code), related infrastructure and resource lists, with dated GitHub signals.','Agent 安全相关 GitHub 仓库：工具与研究实现（含每篇纳入论文自己发布的代码）、相关基础设施、资料清单，以及带采集时间的 GitHub 指标。')})[state.view]}</p></div><div class="stamp"><b>${t('Frozen release','冻结版本')}</b>${t('Field map through','领域地图截至')} 2026-09-30</div></div>
${['resources','oss'].includes(state.view)?resourceSwitch():''}${state.view==='landscape'?'':viewMetrics()}
${['papers','research','resources','teams'].includes(state.view)?`<form class="toolbar" role="search"><input type="search" id="search" value="${escape(state.query)}" aria-label="${t('Search research, authors, venues or teams','搜索论文、作者、会议或团队')}" placeholder="${t('Search research, authors, venues, teams…','搜索论文、作者、会议、团队…')}"><select id="topic" aria-label="${t('Theme or cluster','主题或星团')}">${option('',t('All themes and clusters','全部主题与星团'),state.tag||state.cat?'-':'')}${topicOptions()}</select><select id="year" aria-label="${t('Publication year','发表年份')}">${option('',t('All years','全部年份'),state.year)}${[...new Set(data.papers.map(yearOf).filter(Boolean))].sort().reverse().map(y=>option(y,y,state.year)).join('')}</select>
<select id="group" aria-label="${t('Venue group','会议分组')}">${option('',t('All venue groups','全部会议分组'),state.group)}${Object.entries(groups).map(([id,label])=>option(id,label,state.group)).join('')}</select><select id="venue" aria-label="${t('Conference or journal','会议或期刊')}">${option('',t('All venues','全部会议 / 期刊'),state.venue)}${data.venueRegistry.filter(v=>!state.group||venueFamily(v)===state.group).map(v=>option(v.id,`${v.name} (${included().filter(p=>p.publication.venueId===v.id).length})`,state.venue)).join('')}</select><select id="track" aria-label="${t('Publication track','发表类别')}">${option('',t('All tracks','全部发表类别'),state.track)}${[...new Set([...publicationTracks,...data.papers.map(p=>p.publication.track).filter(Boolean)])].map(x=>option(x,trackName(x),state.track)).join('')}</select>${formsList().length?`<select id="form" aria-label="${t('Paper form','论文形式')}">${option('',t('All paper forms','全部论文形式'),state.form)}${formsList().map(f=>option(f.id,translated(f.en),state.form)).join('')}</select>`:''}<select id="publication" aria-label="${t('Publication status','发表状态')}">${option('',t('All publication states','全部发表状态'),state.publication)}${option('published',t('Published · verified','已发表 · 已核实'),state.publication)}${option('accepted',t('Accepted · official evidence','已录用 · 官方证据'),state.publication)}${option('unverified',t('Publication unverified','发表情况待核实'),state.publication)}</select>${['papers','research'].includes(state.view)?`<label class="check"><input id="pending" type="checkbox" ${state.pending?'checked':''}>${t('Include pending scope','含范围待复核')}</label>`:''}<div id="toolbar-filters" class="toolbar-filters"></div></form>`:''}
<div id="content"></div><footer><span>${t('Agent Safety Atlas · frozen release','Agent Safety Atlas · 冻结版本')}</span><span>${t('Frozen field map v2 · every record traceable to its source','冻结领域地图 v2 · 每条记录可追溯到原始来源')}</span></footer></main><dialog id="detail" aria-label="${t('Research details','研究详情')}"><button class="close" aria-label="${t('Close details','关闭详情')}">×</button><div class="detail"></div></dialog>`;renderOverview();renderContent();bind();initNavigation();countUp()}
const SIZES=[20,50,100];
const byNewest=(a,b)=>yearOf(b).localeCompare(yearOf(a))||(b.date||'').localeCompare(a.date||'');
function sortPapers(ps){return ps.slice().sort(state.sort==='oldest'?(a,b)=>byNewest(b,a):state.sort==='title'?(a,b)=>a.title.localeCompare(b.title):byNewest)}
function paged(items){const pages=Math.max(1,Math.ceil(items.length/state.size));state.page=Math.min(Math.max(1,state.page),pages);return items.slice((state.page-1)*state.size,state.page*state.size)}
function pageList(cur,pages){const out=[];for(let i=1;i<=pages;i++){if(i===1||i===pages||Math.abs(i-cur)<=1||(cur<=3&&i<=5)||(cur>=pages-2&&i>=pages-4))out.push(i);else if(out[out.length-1]!=='…')out.push('…')}return out}
function pager(total,where){if(!total)return '';const pages=Math.max(1,Math.ceil(total/state.size)),cur=state.page,from=(cur-1)*state.size+1,to=Math.min(total,cur*state.size);return `<nav class="pager pager-${where}" aria-label="${where==='top'?t('Pages','分页'):t('Pages (bottom)','分页（底部）')}"><span class="pager-info">${t(`${from}–${to} of ${total}`,`第 ${from}–${to} 条，共 ${total} 条`)}</span><span class="pager-pages"><button data-page="${cur-1}" ${cur<=1?'disabled':''} aria-label="${t('Previous page','上一页')}">‹</button>${pageList(cur,pages).map(n=>n==='…'?'<span class="pager-gap" aria-hidden="true">…</span>':`<button data-page="${n}" class="${n===cur?'active':''}" ${n===cur?'aria-current="page"':''} aria-label="${t('Page '+n,'第 '+n+' 页')}">${n}</button>`).join('')}<button data-page="${cur+1}" ${cur>=pages?'disabled':''} aria-label="${t('Next page','下一页')}">›</button></span>${where==='top'?`<label class="pager-size">${t('Per page','每页')} <select data-size>${SIZES.map(n=>`<option value="${n}" ${n===state.size?'selected':''}>${n}</option>`).join('')}</select></label>`:`<span class="pager-info">${t(`Page ${cur} of ${pages}`,`第 ${cur} / ${pages} 页`)}</span>`}</nav>`}
function topicOptions(){const counts=countTopics();if(!taxonomy)return Object.entries(counts).sort((a,b)=>b[1]-a[1]).map(([x])=>option(x,translated(x),state.tag)).join('');return taxonomy.categories.map(c=>`<optgroup label="${escape(categoryName(c))}">${option('cat:'+c.id,t('All in: ','全部：')+categoryName(c),state.cat?'cat:'+state.cat:'')}${c.topics.map(x=>option(x,`${topicName(x)} (${counts[x]||0})`,state.tag)).join('')}</optgroup>`).join('')}
const num=n=>n==null?'–':Number(n).toLocaleString(state.lang==='zh'?'zh-CN':'en-US');
function viewMetrics(){const v=state.view,inc=included(),h=pipeline?.headline,rs=data.resources,kind=k=>rs.filter(r=>k.includes(r.kind)).length,countries=new Set(data.teams.flatMap(x=>x.locations.map(l=>l.countryCode)).filter(Boolean)).size,ys=inc.map(yearOf).filter(y=>/^\d{4}$/.test(y)).sort();if(v==='landscape'&&h)return hero(inc,h,countries);if(['resources','teams','coverage'].includes(v))return pageBand(v,inc,h,countries);const rows=v==='landscape'?[[t('Included research works','纳入研究'),inc.length],[t('Research institutions','研究机构'),data.teams.length]]:v==='resources'?[[t('Paper artifacts','论文配套资源'),rs.length],[t('Code repositories','代码仓库'),kind(['repository'])],[t('Datasets & benchmarks','数据集与基准'),kind(['dataset','benchmark'])],[t('Models','模型'),kind(['model','model_collection'])],[t('Works with artifacts','有配套资源的研究'),inc.filter(p=>p.resources.length).length,t(`of ${num(inc.length)} included works`,`共 ${num(inc.length)} 项纳入研究`)]]:v==='teams'?[[t('Institutions & groups','研究机构与团队'),data.teams.length],[t('With registry identity (ROR)','有 ROR 登记身份'),data.teams.filter(x=>x.locations.length).length],[t('Countries & regions','国家和地区'),countries],[t('Works with affiliation evidence','有署名证据的研究'),inc.filter(p=>p.teams.length).length,t(`of ${num(inc.length)} included works`,`共 ${num(inc.length)} 项纳入研究`)]]:v==='coverage'&&h?[[t('Discovery routes','发现途径'),(pipeline.sources||[]).length],[t('Records scanned','扫描记录'),h.arxiv_records_scanned+h.catalog_records,t('arXiv + official catalogs','arXiv + 官方目录')],[t('Candidates screened','筛选候选'),h.candidates_screened],[t('Included research works','纳入研究'),inc.length]]:[];return rows.length?`<div class="metrics${v==='landscape'?' headline':''}" style="--cols:${rows.length===6?3:rows.length}">${rows.map(([label,n,note])=>`<div class="metric"><span>${label}</span><strong>${typeof n==='number'?num(n):escape(n)}</strong>${note?`<small>${note}</small>`:''}</div>`).join('')}</div>`:''}
function hero(inc,h,countries){const scanned=h.arxiv_records_scanned+h.catalog_records,steps=[[scanned,t('records scanned','条记录已扫描'),t(`${num(h.arxiv_records_scanned)} arXiv computer-science records and ${num(h.catalog_records)} records from ${h.catalog_families} official venue catalogs`,`${num(h.arxiv_records_scanned)} 条 arXiv 计算机科学记录，以及 ${h.catalog_families} 个官方会议与期刊目录中的 ${num(h.catalog_records)} 条记录`)],[h.candidates_screened,t('candidates screened','条候选经过筛选'),t('DeepSeek first pass and review; Claude Opus adjudication and precision review','DeepSeek 初筛与复核；Claude Opus 裁定与精确度复核')],[inc.length,t('agent-safety works in the Atlas','项 Agent 安全研究收录于图谱'),(w=>w?t(`each with a scope reason, verbatim evidence and its sources; ${num(w)} withdrawn on arXiv are kept and flagged, so the sky and the statistics use the other ${num(inc.length-w)}`,`每项均附范围理由、逐字依据与来源；其中 ${num(w)} 项已在 arXiv 撤回，保留并标注，星图与统计使用其余 ${num(inc.length-w)} 项`):t('each with a scope reason, verbatim evidence and its sources','每项均附范围理由、逐字依据与来源'))(inc.filter(p=>p.attributes?.withdrawal).length)]],pub=inc.filter(p=>['published','accepted'].includes(p.publication.status)).length,os=pipeline?.openSource;return `<section class="hero" aria-label="${t('The collection at a glance','图谱概览')}"><div class="hero-funnel"><div class="hero-eyebrow">${t('From a million records to a curated field map','从百万条记录到一张领域图谱')}</div>${steps.map(([n,label,note],i)=>`<div class="hero-step" style="--w:${Math.max(0.6,n/scanned*100).toFixed(2)}%"><div class="hero-num"><strong data-count="${n}">${num(n)}</strong><span>${label}</span></div><div class="hero-bar" aria-hidden="true"><i></i></div><small>${note}</small></div>`).join('')}<p class="hero-note">${t('Bar length is proportional to the count.','条形长度与数量成正比。')}</p></div><div class="hero-side">${[[data.teams.length,t('research institutions','个研究机构'),t(`in ${countries} countries and regions`,`分布于 ${countries} 个国家和地区`)],[h.repositories,t('open-source repositories','个开源仓库'),os?.counts?t(`${num(os.counts.agent_security)} agent-security tools and research implementations`,`其中 ${num(os.counts.agent_security)} 个为 Agent 安全工具与研究实现`):''],[pub,t('formal publications verified','项正式发表已核实'),t('against official proceedings and publisher records','对照官方论文集与出版方记录')]].filter(([n])=>n!=null).map(([n,label,note])=>`<div class="hero-stat"><strong data-count="${n}">${num(n)}</strong><span>${label}</span><small>${note}</small></div>`).join('')}</div></section>`}
function band(lead,label,parts,stats){const tot=parts.reduce((a,p)=>a+p[1],0)||1;return `<section class="band"><div class="band-lead"><div class="hero-num"><strong data-count="${lead}">${num(lead)}</strong><span>${label}</span></div><div class="band-comp" aria-hidden="true">${parts.map(([,n],i)=>n?`<i style="flex:${n};opacity:${[1,.72,.5,.34,.24][i]||.2}"></i>`:'').join('')}</div><div class="band-keys">${parts.map(([name,n],i)=>`<span><i style="opacity:${[1,.72,.5,.34,.24][i]||.2}"></i>${escape(name)} <b>${num(n)}</b> <em>${(n/tot*100).toFixed(n/tot<.1?1:0)}%</em></span>`).join('')}</div></div><div class="band-stats">${stats.map(([n,label,note,ratio])=>`<div class="band-stat"><strong ${typeof n==='number'?`data-count="${n}"`:''}>${typeof n==='number'?num(n):escape(n)}</strong><span>${label}</span>${ratio!=null?`<div class="band-ratio" aria-hidden="true"><i style="width:${Math.max(1,ratio*100).toFixed(1)}%"></i></div>`:''}${note?`<small>${note}</small>`:''}</div>`).join('')}</div></section>`}
function pageBand(v,inc,h,countries){const pc=(a,b)=>b?Math.round(a/b*100):0;if(v==='resources'){const rs=data.resources,k=ks=>rs.filter(r=>ks.includes(r.kind)).length,code=k(['repository']),dsets=k(['dataset','benchmark']),models=k(['model','model_collection']),withArt=inc.filter(p=>p.resources.length).length,withCode=inc.filter(hasCode).length,lic=rs.filter(r=>r.license).length;return band(rs.length,t('artifacts released with included papers','项纳入论文配套资源'),[[t('Code repositories','代码仓库'),code],[t('Datasets & benchmarks','数据集与基准'),dsets],[t('Models','模型'),models],[t('Project pages & other','项目页及其他'),rs.length-code-dsets-models]],[[withArt,t('works release artifacts','项研究发布了配套资源'),t(`${pc(withArt,inc.length)}% of ${num(inc.length)} included works`,`占 ${num(inc.length)} 项纳入研究的 ${pc(withArt,inc.length)}%`),withArt/inc.length],[withCode,t('works link their own code','项研究链接了自有代码'),t(`${pc(withCode,inc.length)}% of included works`,`占纳入研究的 ${pc(withCode,inc.length)}%`),withCode/inc.length],[lic,t('artifacts with a recorded license','项资源记录了许可证'),t(`${pc(lic,rs.length)}% of artifacts; unknown licenses are marked`,`占资源的 ${pc(lic,rs.length)}%；许可证未知者已标注`),lic/rs.length]])}if(v==='teams'){const ror=data.teams.filter(x=>x.locations.length).length,cc=new Map();for(const p of inc)for(const c of countriesOf(p))cc.set(c,(cc.get(c)||0)+1);const top=[...cc].sort((a,b)=>b[1]-a[1]).slice(0,3),withAff=inc.filter(p=>p.teams.length).length;return band(data.teams.length,t('institutions and research groups','个研究机构与团队'),[[t('Registry identity (ROR)','有 ROR 登记身份'),ror],[t('Named in the source only','仅见于来源署名'),data.teams.length-ror]],[[countries,t('countries and regions','个国家和地区'),t(`most works: ${top.map(([c,n])=>`${countryName(c)} ${num(n)}`).join(' · ')}`,`研究最多：${top.map(([c,n])=>`${countryName(c)} ${num(n)}`).join(' · ')}`),null],[withAff,t('works with affiliation evidence','项研究有署名证据'),t(`${pc(withAff,inc.length)}% of ${num(inc.length)} included works`,`占 ${num(inc.length)} 项纳入研究的 ${pc(withAff,inc.length)}%`),withAff/inc.length]])}if(v==='coverage'&&h){const sc=h.arxiv_records_scanned+h.catalog_records,fin=pipeline.screening?.final||{},opus=(pipeline.screening?.stages||[]).filter(x=>x.id.startsWith('opus')||x.id==='stage3').reduce((a,x)=>a+x.count,0);return band(sc,t('records scanned','条记录已扫描'),[[t('arXiv computer-science records','arXiv 计算机科学记录'),h.arxiv_records_scanned],[t(`official catalogs (${h.catalog_families})`,`官方目录（${h.catalog_families} 个）`),h.catalog_records]],[[h.candidates_screened,t('candidates screened','条候选经过筛选'),t(`${(h.candidates_screened/sc*100).toFixed(1)}% of records matched keywords or catalogs`,`${(h.candidates_screened/sc*100).toFixed(1)}% 的记录命中关键词或目录`),h.candidates_screened/sc],[fin.include||0,t('included by screening','项经筛选纳入'),t(`${((fin.include||0)/h.candidates_screened*100).toFixed(1)}% of candidates; ${num(inc.length)} works on the Atlas in total`,`占候选的 ${((fin.include||0)/h.candidates_screened*100).toFixed(1)}%；图谱共收录 ${num(inc.length)} 项`),(fin.include||0)/h.candidates_screened],[opus,t('Claude Opus reviews','次 Claude Opus 复核'),t('adjudication, precision review and full-text resolution','裁定、精确度复核与全文判定'),null]])}return ''}
