async function ensureTranslations(){if(Object.keys(translations).length)return;try{const r=await fetch('./data/translations.zh.json');if(r.ok)translations=await r.json()}catch{}}
function countryName(cc){for(const x of data.teams)for(const l of x.locations)if(l.countryCode===cc)return l.country;return cc}
function activeFilters(){const pub={published:t('Published · verified','已发表 · 已核实'),accepted:t('Accepted · official evidence','已录用 · 官方证据'),unverified:t('Publication unverified','发表情况待核实')},f=[];if(state.query)f.push(['query',`“${state.query}”`]);if(state.cat)f.push(['cat',categoryName(categoryOf(state.cat))||state.cat]);if(state.tag)f.push(['tag',topicName(state.tag)]);if(state.team)f.push(['team',t('Institution: ','机构：')+(teamById.get(state.team)?.name||state.team)]);if(state.year)f.push(['year',state.year]);if(state.group)f.push(['group',groupNames()[state.group]||state.group]);if(state.venue)f.push(['venue',data.venueRegistry.find(v=>v.id===state.venue)?.name||state.venue]);if(state.track)f.push(['track',trackName(state.track)]);if(state.publication)f.push(['publication',pub[state.publication]||state.publication]);if(state.form)f.push(['form',t('Form: ','形式：')+translated(formsList().find(x=>x.id===state.form)?.en||state.form)]);if(state.country)f.push(['country',t('Country/region: ','国家/地区：')+countryName(state.country)]);if(state.rel)f.push(['rel',t('Added in update ','新增于更新 ')+state.rel]);if(state.facet)f.push(['facet',facetChip(t,state.facet)]);if(state.art)f.push(['art',state.art==='code'?t('With released code','有公开代码'):t('With released artifacts','有配套资源')]);if(state.pending)f.push(['pending',t('Including pending scope','含范围待复核')]);return f.length?`<div class="active-filters"><span class="muted">${t('Filters','筛选')}:</span>${f.map(([k,label])=>`<button class="filter-chip" data-clear="${k}" aria-label="${escape(t('Remove filter: ','移除筛选：')+label)}">${escape(label)}<span aria-hidden="true">×</span></button>`).join('')}<button class="textlink" data-reset>${t('Clear all','全部清除')}</button></div>`:''}
function researchList(papers){const list=sortPapers(papers),rows=paged(list);return `<section class="panel results" id="results"><div class="panel-title"><strong>${t('Research index','研究索引')}</strong><span class="muted" role="status">${list.length} ${t('research works','项研究')}</span><span class="panel-tools"><label class="sort">${t('Sort','排序')} <select data-sort>${[['newest',t('Newest first','最新优先')],['oldest',t('Oldest first','最早优先')],['title',t('Title A–Z','标题 A–Z')]].map(([v,l])=>option(v,l,state.sort)).join('')}</select></label>${downloadsOpen?`<a class="textlink" href="./data/research-records.csv" download>${t('Download CSV','下载 CSV')} ↓</a>`:''}${state.view==='papers'&&!state.guideSlug?`<button class="textlink" data-reset>↑ ${t('Back to the directory','回到目录')}</button>`:''}</span></div>${activeFilters()}${list.length?pager(list.length,'top')+rows.map(paperRow).join('')+pager(list.length,'bottom'):empty()}</section>`}
function landscape(mode=''){const ex=mode==='explore',base=ex?filtered(true).filter(p=>!p.attributes?.withdrawal):filtered(true),counts=countTopics(base),resByWork=new Map();for(const r of data.resources)for(const id of (r.workIds||[r.workId])){if(!resByWork.has(id))resByWork.set(id,[]);resByWork.get(id).push(r.id)}const main=taxonomy.categories.filter(c=>!c.other),nTopics=main.reduce((n,c)=>n+c.topics.length,0),max=Math.max(1,...main.flatMap(c=>c.topics.map(x=>counts[x]||0)));
const tiles=taxonomy.categories.map(c=>{const ps=base.filter(p=>topicsOf(p).some(x=>c.topics.includes(x))),rs=new Set(ps.flatMap(p=>resByWork.get(p.workId)||[])),tm=new Set(ps.flatMap(p=>p.teams)),on=state.cat===c.id;return `<article class="mcat${on?' is-active':''}${c.other?' mcat-other':''}" style="--cat:${c.color}"><button class="mcat-head"${ex&&!c.other?' data-cat-view="papers"':''} data-cat="${escape(c.id)}" aria-pressed="${on}" title="${escape(t('List every work in this group','列出该大类的全部研究'))}"><span>${escape(categoryName(c))}</span><b>${ps.length}</b></button><ul class="mtopics">${c.topics.map(x=>{const n=counts[x]||0,sel=state.tag===x;const tp=formsList().length?base.filter(p=>topicsOf(p).includes(x)):[];return `<li><button class="mtopic${sel?' is-active':''}${tp.length?' has-forms':''}" ${ex?'data-tag':'data-topic'}="${escape(x)}" aria-pressed="${sel}" ${n?'':'disabled'} style="--w:${c.other||tp.length?0:(n/max*100).toFixed(1)}%"${x==='Topic not labelled'?` title="${escape(t('Works still awaiting scope review; tick “Include pending scope” to count them.','仍待范围复核的研究；勾选“含范围待复核”后计入。'))}"`:tp.length?` title="${escape(formTitle(tp))}"`:''}><span>${escape(topicName(x))}</span><b>${n}</b>${tp.length&&!c.other?formBar(tp,(n/max*100).toFixed(1)):''}</button></li>`}).join('')}</ul><div class="mcat-foot"><button class="textlink" data-cat-view="resources" data-cat="${escape(c.id)}">${rs.size} ${t('resources','项资源')}</button>${ex?`<button class="textlink" data-ex-inst="${escape(c.id)}">${tm.size} ${t('institutions','个机构')}</button>`:`<button class="textlink" data-cat-view="teams" data-cat="${escape(c.id)}">${tm.size} ${t('institutions','个机构')}</button>`}</div></article>`}).join('');
return `<section class="landscape panel" aria-labelledby="landscape-title"><div class="landscape-head"><div><h2 id="landscape-title">${t('Research landscape','研究全景')}</h2><p class="muted">${t(`${num(base.length)} works of the collection in the ${main.length} themes and ${nTopics} consensus clusters of the frozen field map. Each card counts the theme's cluster members, so card totals add up to 4,998; with the 50 works assigned to a theme by text voting the theme totals are 5,048 (for example 840 rather than 835 for T1). Works outside every cluster (text-assigned, unassigned, or first public after 30 September 2026) are listed under “Outside the clusters”. ${ex?'Bars are split by paper form; click a theme or cluster for its papers.':'Counts follow the search and filters above.'}`,`收录中的 ${num(base.length)} 项研究，按冻结领域地图的 ${main.length} 个主题和 ${nTopics} 个共识星团归组。每张卡片只计该主题的星团成员，合计 4,998 篇；加上按文本投票归入主题的 50 篇，主题合计为 5,048（例如 T1 为 840 而不是 835）。不属于任何星团的研究（按文本归入、未归类、或 2026 年 9 月 30 日之后首次公开）列在“星团之外”。${ex?'条形按论文形式拆分；点击主题或星团查看论文。':'计数随上方检索与筛选变化。'}`)}</p></div><a class="textlink" href="./tables/clusters_61.csv" download>${t('Cluster list (CSV)','星团列表（CSV）')} ↓</a></div>${formLegend()}<div class="matrix">${tiles}</div><p class="landscape-note muted">${t('Verified conference or journal versions take precedence and preprints stay linked; an unverified venue does not mean preprint-only. Counts depend on source coverage.','优先显示已核实的会议或期刊版本并保留预印本链接；发表信息待核实不代表只有预印本。计数受来源覆盖范围影响。')} <button class="textlink" data-view="coverage">${t('Coverage and gaps','覆盖与缺口')} ↗</button></p></section>`}
function research(papers){const counts=Object.entries(countTopics()).sort((a,b)=>b[1]-a[1]),max=Math.max(1,...counts.map(([,n])=>n));return `<div class="layout">${researchList(papers)}<aside><section class="sidecard"><h2>${t('Safety topics','安全主题')}</h2>${counts.slice(0,9).map(([tag,n])=>`<div class="themebar"><button data-tag="${escape(tag)}"><span>${escape(topicName(tag))}</span><span>${n}</span></button><div class="track"><div class="fill" style="width:${n/max*100}%${taxonomy?';background:'+topicColor(tag):''}"></div></div></div>`).join('')}<p class="muted">${t('A work may belong to multiple topics.','一项研究可归入多个主题。')}</p>${taxonomy?`<button class="textlink" data-view="landscape">${t('All topics in the landscape','在研究全景中查看全部主题')} ↗</button>`:''}</section><section class="sidecard dark"><span class="kicker">${t('PUBLICATION FIRST','正式发表优先')}</span><h2>${t('Follow the official record.','以官方发表记录为准。')}</h2><p>${t('Verified conference or journal versions take precedence. Preprints remain linked. Main tracks, Findings and workshops stay distinct.','优先显示已核实的会议或期刊版本，同时保留预印本链接。主会、Findings 与研讨会分别标注。')}</p></section><section class="sidecard"><h2>${t('Interpreting the collection','如何理解收录情况')}</h2><p class="muted">${t('Counts depend on source coverage. Original titles and source excerpts are preserved. An unverified venue is not proof of preprint-only status.','计数受来源覆盖范围影响。保留论文原始标题与来源原文；发表信息待核实不代表论文只有预印本。')}</p><button class="textlink" data-view="coverage">${t('Inspect coverage and gaps','查看覆盖与缺口')} ↗</button></section></aside></div>`}
