function resourceSwitch(){if(!ossAvailable)return '';const n=pipeline?.openSource?.included;return `<nav class="subviews" aria-label="${t('Open source & resources','开源与资源')}">${[['resources',t('Paper artifacts','论文配套资源'),data.resources.length,t('Released with included papers: code, datasets, models, project pages','纳入论文配套发布：代码、数据集、模型、项目页')],['oss',t('Open-source repositories','开源仓库'),n,t('GitHub landscape incl. every included paper’s own code, plus tools, infrastructure and lists','GitHub 全景：含纳入论文自己的代码，以及工具、基础设施与清单')]].map(([id,label,count,note])=>`<button data-view="${id}" class="${state.view===id?'active':''}" aria-pressed="${state.view===id}"><b>${label}</b>${count!=null?`<strong>${num(count)}</strong>`:''}<small>${note}</small></button>`).join('')}</nav>`}
const repoKey=u=>(u||'').match(/github\.com\/([^/]+\/[^/#?]+)/i)?.[1]?.replace(/\.git$/,'');
function resources(papers){const ids=new Set(papers.map(p=>p.workId)),rs=data.resources.filter(r=>(r.workIds||[r.workId]).some(id=>ids.has(id))),rows=paged(rs);return `<div class="hint">${t('Public access does not establish permission to reuse. Unknown licenses are marked; resources have not been independently reproduced.','公开可访问不等于具有再利用许可。未知许可证已明确标注，资源尚未经过独立复现。')}</div>${activeFilters()}<div id="results" class="results">${rs.length?`${pager(rs.length,'top')}<div class="grid">${rows.map(r=>`<article class="panel resource"><span class="overline">${typeName(r.kind)}</span><h2>${escape(r.title)}</h2><p>${text(r,'summary')}</p><div class="tags">${chip(accessName(r))}${chip(r.license||t('License unverified','许可证待核实'))}${chip(r.version?t('Revision ','版本 ')+String(r.version).slice(0,12):t('Revision unknown','版本未知'))}</div>${r.attributes.availability_note?`<p class="muted">${escape(translated(r.attributes.availability_note))}</p>`:''}<div class="rowfoot"><button data-paper="${escape(papers.find(p=>(r.workIds||[r.workId]).includes(p.workId))?.id||'')}">${t('Research & data details','研究及数据详情')}</button>${ossAvailable&&repoKey(r.url)?`<a href="#oss?rq=${encodeURIComponent(repoKey(r.url))}">${t('In repository list','在仓库列表中查看')}</a>`:''}${external(r.url,t('Source resource','资源来源'))}</div></article>`).join('')}</div>${pager(rs.length,'bottom')}`:empty()}</div>`}
function teams(papers){const ids=new Set(papers.map(p=>p.id)),ts=data.teams.map(x=>[x,x.papers.filter(id=>ids.has(id)).length]).filter(([,n])=>n).sort((a,b)=>b[1]-a[1]||a[0].name.localeCompare(b[0].name)),rows=paged(ts);return `<div class="hint">${t('Institutions and named groups are preserved separately. Historical names may need identity resolution. Coauthorship does not prove shared lab membership.','机构与具名研究组分别保留，历史名称仍可能需要合并核验。共同署名不等于隶属同一实验室。')}</div>${activeFilters()}<div id="results" class="results">${ts.length?`${pager(ts.length,'top')}<div class="grid">${rows.map(([x,n])=>`<article class="panel team"><span class="overline">${escape(entityTypeName(x.type))}</span><h2>${teamFlag(x)}${escape(x.name)}</h2><p>${x.locations.length?x.locations.map(l=>escape(l.city+' · '+l.country)).join(' / '):t('Location unverified','地点待核实')}</p><div class="rowfoot"><button data-team="${escape(x.id)}">${n} ${t('linked works','项关联研究')} ↗</button>${x.locations[0]?external(x.locations[0].source,'ROR'):''}</div></article>`).join('')}</div>${pager(ts.length,'bottom')}`:empty()}</div>`}
