function renderOverview(){const el=$('#overview');if(!el)return;state.metric=state.view==='teams'?'teams':'papers';Object.assign(mapView,{k:1,x:0,y:0});if(state.view==='papers'){el.innerHTML=landscape();return}el.innerHTML=state.view==='teams'?geoSection(true):geoSection(false);initMap()}
const MAP_W=960,MAP_H=440,MAP_MAX=16,MAP_GAP=26,mapView={k:1,x:0,y:0},mapScale={};let mapPts=[],mapClusters=[],mapDrag=null,mapFrame,hintTimer;
function mapBlock(){return `<div class="map-tools"><span class="map-measure">${state.metric==='teams'?t('Bubble size: number of institutions','气泡大小：机构数'):t('Bubble size: distinct linked works','气泡大小：关联研究数')}</span><div class="zoom" role="group" aria-label="${t('Map zoom','地图缩放')}"><button data-zoom="in" aria-label="${t('Zoom in','放大')}">+</button><button data-zoom="out" aria-label="${t('Zoom out','缩小')}">−</button><button data-zoom="reset">${t('Reset view','复位')}</button></div></div><div class="map-wrap"><svg class="map" id="map" viewBox="0 0 ${MAP_W} ${MAP_H}" role="group" aria-label="${t('Research institution locations; nearby institutions are grouped into bubbles','研究机构地点；相邻机构合并为气泡')}"><g id="map-land">${land?land.features.map(f=>`<path class="land" d="${geometryPath(f.geometry)}"/>`).join(''):''}${borders?borders.features.map(f=>`<path class="border${/Disputed|control|Indefinite|Claim|Indeterminant/i.test(f.properties.featurecla||'')?' disputed':''}" d="${linePath(f.geometry)}"/>`).join(''):''}</g><g id="map-bubbles"></g></svg><div class="map-hint" id="map-hint" hidden>${t('Hold Ctrl (⌘ on Mac) and scroll to zoom','按住 Ctrl（Mac 为 ⌘）并滚动即可缩放')}</div><div class="map-panel" id="map-panel" hidden></div></div><p class="muted">${t('Nearby institutions merge into one bubble. Its size shows the number of institutions or of distinct linked works (a work with several institutions counts once). Base map: Natural Earth; dashed lines mark disputed or undetermined boundaries, which imply no political position. Zoom with +/− or Ctrl + scroll, drag to pan, and click a bubble to zoom in or list its institutions.','相邻机构会合并为一个气泡，气泡大小表示机构数或关联研究数（同一研究涉及多个机构只计一次）。底图：Natural Earth；虚线表示存在争议或未定的边界，不表达政治立场。可用 +/− 或 Ctrl + 滚轮缩放、拖动平移，点击气泡放大或查看机构列表。')}</p>`}
function mapPoints(){const inc=new Set(included().map(p=>p.id));return data.teams.filter(x=>x.locations.length).flatMap(x=>x.locations.map(l=>({team:x,loc:l,px:(l.lon+180)/360*MAP_W,py:(90-l.lat)/180*MAP_H,works:x.papers.filter(id=>inc.has(id))}))).sort((a,b)=>b.works.length-a.works.length)}
function finishCluster(c){const m=c.members,{k,x,y}=mapView;c.teams=new Set(m.map(p=>p.team.id));c.works=new Set(m.flatMap(p=>p.works));c.w=state.metric==='papers'?c.works.size:c.teams.size;c.px=m.reduce((s,p)=>s+p.px,0)/m.length;c.py=m.reduce((s,p)=>s+p.py,0)/m.length;c.sx=x+k*c.px;c.sy=y+k*c.py;c.spread=Math.max(...m.map(p=>Math.hypot(p.px-c.px,p.py-c.py)));return c}
function clusterPoints(u,scale){const {k,x,y}=mapView,gap=MAP_GAP*u,cl=[];for(const p of mapPts){const sx=x+k*p.px,sy=y+k*p.py;let best=null,bd=gap;for(const c of cl){const d=Math.hypot(c.sx-sx,c.sy-sy);if(d<bd){bd=d;best=c}}if(best){best.members.push(p);best.sx+=(sx-best.sx)/best.members.length;best.sy+=(sy-best.sy)/best.members.length}else cl.push({sx,sy,members:[p]})}cl.forEach(finishCluster);if(!scale)return cl;const rad=c=>u*Math.min(30,Math.max(6,3+scale*Math.sqrt(c.w)));for(const c of cl)c.r=rad(c);for(let merged=true;merged;){merged=false;search:for(let i=0;i<cl.length;i++)for(let j=i+1;j<cl.length;j++){const a=cl[i],b=cl[j];if(a.w&&b.w&&Math.hypot(a.sx-b.sx,a.sy-b.sy)<(a.r+b.r)*.92){a.members.push(...b.members);finishCluster(a);a.r=rad(a);cl.splice(j,1);merged=true;break search}}}return cl}
function mapUnit(){const w=$('#map')?.getBoundingClientRect().width;return w?MAP_W/w:1}
function mapRadiusScale(u){const key=state.metric+'|'+u.toFixed(2);if(!mapScale[key]){const saved={...mapView};Object.assign(mapView,{k:1,x:0,y:0});mapScale[key]=24/Math.sqrt(Math.max(1,...clusterPoints(u).map(c=>c.w)));Object.assign(mapView,saved)}return mapScale[key]}
function clusterLabel(c){const cities=[...new Set(c.members.map(p=>p.loc.city))],works=`${c.works.size} ${t('linked works','项关联研究')}`;return c.teams.size===1?`${c.members[0].team.name} · ${cities[0]} · ${works}`:`${c.teams.size} ${t('institutions','个机构')} · ${works} · ${cities.slice(0,3).join(', ')}${cities.length>3?' …':''}`}
function drawMap(){const svg=$('#map');if(!svg)return;$('#map-land').setAttribute('transform',`translate(${mapView.x.toFixed(2)} ${mapView.y.toFixed(2)}) scale(${mapView.k.toFixed(4)})`);const u=mapUnit(),s=mapRadiusScale(u),g=$('#map-bubbles');mapClusters=clusterPoints(u,s).filter(c=>c.w>0&&c.sx>-40*u&&c.sx<MAP_W+40*u&&c.sy>-40*u&&c.sy<MAP_H+40*u).sort((a,b)=>b.w-a.w);g.setAttribute('font-size',(11*u).toFixed(2));g.innerHTML=mapClusters.map((c,i)=>{const label=clusterLabel(c),cx=c.sx.toFixed(1),cy=c.sy.toFixed(1);return `<g class="map-bubble${c.teams.size>1?' is-cluster':''}" tabindex="0" role="button" data-cluster="${i}" aria-label="${escape(label)}"><circle cx="${cx}" cy="${cy}" r="${c.r.toFixed(1)}"/>${c.r>=9*u?`<text x="${cx}" y="${cy}" dy=".35em">${c.w}</text>`:''}<title>${escape(label)}</title></g>`}).join('');svg.classList.toggle('is-zoomed',mapView.k>1.01)}
function scheduleMap(){cancelAnimationFrame(mapFrame);mapFrame=requestAnimationFrame(drawMap)}
function clampMap(){mapView.x=Math.min(0,Math.max(MAP_W*(1-mapView.k),mapView.x));mapView.y=Math.min(0,Math.max(MAP_H*(1-mapView.k),mapView.y))}
function zoomMap(factor,cx=MAP_W/2,cy=MAP_H/2){const k=Math.min(MAP_MAX,Math.max(1,mapView.k*factor)),f=k/mapView.k;mapView.x=cx-(cx-mapView.x)*f;mapView.y=cy-(cy-mapView.y)*f;mapView.k=k;clampMap();scheduleMap()}
function svgPoint(e){const r=$('#map').getBoundingClientRect();return [(e.clientX-r.left)/r.width*MAP_W,(e.clientY-r.top)/r.height*MAP_H]}
function showMapHint(){const h=$('#map-hint');if(!h)return;h.hidden=false;clearTimeout(hintTimer);hintTimer=setTimeout(()=>{h.hidden=true},1500)}
function openCluster(i){const c=mapClusters[i];if(!c)return;if(c.teams.size>1&&mapView.k<MAP_MAX&&c.spread*MAP_MAX>=MAP_GAP*mapUnit()/2){const k=Math.min(MAP_MAX,mapView.k*2.5);mapView.k=k;mapView.x=MAP_W/2-k*c.px;mapView.y=MAP_H/2-k*c.py;clampMap();drawMap();$('#map-panel').hidden=true;return}const inc=new Set(included().map(p=>p.id)),rows=[...c.teams].map(id=>teamById.get(id)).map(x=>[x,x.papers.filter(id=>inc.has(id)).length]).sort((a,b)=>b[1]-a[1]||a[0].name.localeCompare(b[0].name)),places=[...new Set(c.members.map(p=>p.loc.city+' · '+p.loc.country))],panel=$('#map-panel');panel.innerHTML=`<div class="map-panel-head"><strong>${escape(places.slice(0,2).join(' / '))}${places.length>2?' …':''}</strong><button class="close-panel" data-close-panel aria-label="${t('Close list','关闭列表')}">×</button></div><p class="muted">${c.teams.size} ${t('institutions','个机构')} · ${c.works.size} ${t('linked works','项关联研究')}</p><ul>${rows.map(([x,n])=>`<li><button data-team="${escape(x.id)}">${escape(x.name)}</button><span>${n}</span></li>`).join('')}</ul>`;panel.hidden=false;panel.querySelector('li button')?.focus()}
function initMap(){const svg=$('#map');if(!svg)return;mapPts=mapPoints();drawMap();svg.addEventListener('wheel',e=>{if(!(e.ctrlKey||e.metaKey)){showMapHint();return}e.preventDefault();const [cx,cy]=svgPoint(e);zoomMap(Math.exp(-e.deltaY*0.002),cx,cy)},{passive:false});svg.addEventListener('pointerdown',e=>{if(e.button===0)mapDrag={x:e.clientX,y:e.clientY,vx:mapView.x,vy:mapView.y,moved:false}});svg.addEventListener('pointermove',e=>{if(!mapDrag||(!mapDrag.moved&&Math.hypot(e.clientX-mapDrag.x,e.clientY-mapDrag.y)<4))return;if(!mapDrag.moved){mapDrag.moved=true;svg.setPointerCapture(e.pointerId)}const r=svg.getBoundingClientRect();mapView.x=mapDrag.vx+(e.clientX-mapDrag.x)/r.width*MAP_W;mapView.y=mapDrag.vy+(e.clientY-mapDrag.y)/r.height*MAP_H;clampMap();scheduleMap()});for(const type of ['pointerup','pointercancel'])svg.addEventListener(type,()=>{mapDrag=null});svg.addEventListener('dblclick',e=>{if(e.target.closest('[data-cluster]'))return;e.preventDefault();const [cx,cy]=svgPoint(e);zoomMap(2,cx,cy)})}
function coverage(){return dataSources()}
function dataSources(){const p=pipeline,inc=included();if(!p)return `<div class="empty"><strong>${t('Source summary unavailable','来源摘要暂不可用')}</strong></div>`;const h=p.headline,v=p.verification,fin=p.screening.final,os=p.openSource,src=p.sources,earlier=src.find(x=>x.id==='earlier_releases')?.on_site||0,unverified=inc.filter(x=>!['published','accepted'].includes(x.publication.status)).length,noAff=inc.filter(x=>!x.teams.length).length,routeName={arxiv_api:t('arXiv keyword search (API queries R1–R3)','arXiv 关键词检索（API 查询 R1–R3）'),arxiv_oai:t('arXiv bulk harvest (OAI-PMH, all computer-science records)','arXiv 全量获取（OAI-PMH，全部计算机科学记录）'),conference_exports:t('NeurIPS / ICML / ICLR official exports (papers not on arXiv)','NeurIPS / ICML / ICLR 官方导出（未上 arXiv 的论文）'),nlp_ml_catalogs:t('ACL Anthology, PMLR and USENIX catalogs (papers not on arXiv)','ACL Anthology、PMLR 与 USENIX 目录（未上 arXiv 的论文）'),more_venues:t('AAAI, IJCAI, S&P, CCS, NDSS, AIES, FAccT, CHI, WWW, ICSE, FSE, ASE, SaTML, EuroS&P, AsiaCCS, COLM, TMLR, AAMAS','AAAI、IJCAI、S&P、CCS、NDSS、AIES、FAccT、CHI、WWW、ICSE、FSE、ASE、SaTML、EuroS&P、AsiaCCS、COLM、TMLR、AAMAS'),discovery_backlog:t('Earlier discovery backlog (topic searches, citations, curated lists)','早期发现积压（主题检索、引文、精选清单）'),earlier_releases:t('Earlier curated releases (seed lists, catalog and citation work)','早期整理版本（种子清单、目录与引文整理）')},stageName={stage1:t('DeepSeek first pass — every candidate','DeepSeek 初筛——每条候选'),stage2:t('DeepSeek review — first-pass inclusions and boundary cases','DeepSeek 复核——初筛纳入与边界候选'),stage3:t('Claude Opus adjudication — where the review did not confirm inclusion','Claude Opus 裁定——复核未确认纳入者'),opus_review:t('Claude Opus review — every inclusion; from policy v4 every first-pass forward','Claude Opus 复核——每项纳入；自 v4 起覆盖初筛转交的全部候选'),opus_fulltext:t('Claude Opus full-text resolution — boundary cases','Claude Opus 全文判定——边界候选'),owner_review:t('Project owner manual review — remaining boundary cases','项目负责人人工复核——剩余边界候选'),opus_audit:t('Claude Opus audit — first-pass exclusions cited by curated reading lists','Claude Opus 抽查——被精选论文清单收录、却在初筛中排除的候选')};
return `<section class="panel section"><div class="eyebrow">${t('FROM RECORDS TO THE ATLAS','从记录到图谱')}</div><h2>${t('How the collection was built','收录是如何构建的')}</h2><div class="funnel">${[[t('Records scanned','扫描记录'),h.arxiv_records_scanned+h.catalog_records,t(`${num(h.arxiv_records_scanned)} arXiv records + ${num(h.catalog_records)} official proceedings records`,`${num(h.arxiv_records_scanned)} 条 arXiv 记录 + ${num(h.catalog_records)} 条官方会议与期刊记录`)],[t('Candidates screened','筛选候选'),h.candidates_screened,t('keyword matches and catalog hits, deduplicated','关键词与目录命中，已去重')],[t('Included by screening','筛选纳入'),fin.include||0,t(`${num(fin.boundary||0)} boundary cases still open`,`${num(fin.boundary||0)} 项边界候选待定`)],[t('Works on the Atlas','图谱收录'),inc.length,t(`including ${num(earlier)} from earlier curated releases`,`含早期整理版本 ${num(earlier)} 项`)]].map(([label,n,note],i)=>`${i?'<span class="funnel-arrow" aria-hidden="true">→</span>':''}<div class="funnel-step"><span>${label}</span><strong>${num(n)}</strong><small>${note}</small></div>`).join('')}</div>
<p class="muted">${t('Counts are regenerated from the pipeline files on every site update. Candidate counts overlap across routes before deduplication; the same work found twice is screened once.','每次更新网站时，各项数字都从流程文件重新生成。去重前不同途径的候选存在重叠；同一研究被多条途径找到时只筛选一次。')}</p></section>
<section class="panel section"><h2>${t('Discovery routes','发现途径')}</h2><div class="tablewrap"><table class="coverage sources-table"><thead><tr><th>${t('Route','途径')}</th><th class="num">${t('Candidates','候选')}</th><th class="num">${t('Screened','已筛选')}</th><th class="num">${t('On the Atlas','图谱收录')}</th></tr></thead><tbody>${src.map(r=>`<tr><td>${escape(routeName[r.id]||r.label)}${r.id==='arxiv_oai'&&r.scanned?`<small>${t(`${num(r.scanned)} records scanned · ${num(r.keyword_matches)} keyword matches · ${num(r.candidates)} not already found by keyword search`,`扫描 ${num(r.scanned)} 条记录 · 关键词命中 ${num(r.keyword_matches)} 条 · 其中 ${num(r.candidates)} 条未被关键词检索覆盖`)}</small>`:''}</td><td class="num">${r.candidates!=null?num(r.candidates):'—'}</td><td class="num">${r.screened!=null?num(r.screened):'—'}</td><td class="num">${num(r.on_site)}</td></tr>`).join('')}<tr class="total"><td>${t('Total','合计')}</td><td></td><td class="num">${num(h.candidates_screened)}</td><td class="num">${num(inc.length)}</td></tr></tbody></table></div></section>
<section class="panel section"><h2>${t('Official catalogs','官方目录')}</h2><p class="muted">${t(`${p.catalogs.length} venue catalogs (${num(h.catalog_records)} records) are used twice: to find papers that never appeared on arXiv, and to verify where arXiv papers were formally published.`,`共 ${p.catalogs.length} 个会议与期刊目录（${num(h.catalog_records)} 条记录），用于两件事：找到从未上 arXiv 的论文，以及核实 arXiv 论文的正式发表位置。`)}</p><div class="catalog-grid">${p.catalogs.map(c=>`<div><span>${escape(c.label)}</span><b>${num(c.records)}</b></div>`).join('')}</div></section>
<section class="panel section"><h2>${t('Screening','筛选流程')}</h2><div class="tablewrap"><table class="coverage"><thead><tr><th>${t('Stage','阶段')}</th><th class="num">${t('Candidates','候选数')}</th></tr></thead><tbody>${p.screening.stages.map(x=>`<tr><td>${escape(stageName[x.id]||x.label)}</td><td class="num">${num(x.count)}</td></tr>`).join('')}</tbody></table></div><div class="tags">${[['include',t('Included','纳入')],['exclude',t('Excluded','排除')],['boundary',t('Boundary, open','边界待定')],['retrieval_failed',t('Text unavailable','无法获取文本')]].filter(([k])=>fin[k]).map(([k,label])=>chip(`${label}: ${num(fin[k])}`)).join('')}</div><p class="muted">${t('Scope follows the Atlas definition of agent safety: digital agents and, from policy v4 (26 September 2026), embodied or physical-world agents driven by a learned policy or foundation model (robots and VLA agents, RL agents in control tasks, learned driving and drone agents); classical control without a learned agent is out of scope. Each decision keeps the deciding stage, a reason and a verbatim quote from the abstract or full text. Decisions are model-made with Claude Opus review; only the remaining boundary cases were decided by the project owner’s manual review (stage list above).','范围以本图谱的 Agent 安全定义为准：数字智能体，以及自范围政策 v4（2026 年 9 月 26 日）起纳入的、由学习型策略或基础模型驱动的具身与物理世界智能体（机器人与 VLA 智能体、控制任务中的强化学习智能体、学习型自动驾驶与无人机智能体）；不含学习型智能体的经典控制不在范围内。每项判断都记录判定阶段、理由，以及摘要或全文中的逐字引文。判断由模型做出并经 Claude Opus 复核；仅剩余的边界候选由项目负责人人工复核（见上方阶段列表）。')}</p></section>
<section class="panel section"><h2>${t('Verification of included works','纳入研究的核验')}</h2><div class="metrics coverage-metrics">${[[t('Formal publication verified','正式发表已核实'),v.publication_verified,inc.length],[t('With affiliation evidence','有署名证据'),v.with_affiliations,inc.length],[t('With released artifacts','有配套资源'),v.with_resources,inc.length],[t('Affiliation strings matched to ROR','署名单位匹配 ROR'),v.affiliation_strings_matched,v.affiliation_strings]].map(([label,n,d])=>`<div class="metric"><span>${label}</span><strong>${num(n)}</strong><small>${t('of','共')} ${num(d)}</small></div>`).join('')}</div><p class="muted">${t(`Publications are matched to official proceedings by title and authors, to publisher deposits in Crossref, and to the monthly dblp XML snapshot where the dblp record links the official proceedings page (${num(v.publication_dblp||0)} works). Leads from OpenAlex and dblp count only after one of these checks; an unverified publication is not necessarily unpublished. ${num(v.withdrawn||0)} included works are withdrawn on arXiv (checked against arXiv's own records); they stay listed with the withdrawal notice. Affiliations are copied verbatim from ${num(v.full_texts_read)} full texts and official catalogs, then matched to the ROR registry; no current employment or location is inferred.`,`正式发表通过标题与作者与官方论文集匹配，并参考出版方在 Crossref 登记的记录，以及 dblp 月度 XML 快照中链接到官方论文集页面的记录（${num(v.publication_dblp||0)} 篇）。来自 OpenAlex 与 dblp 的线索须通过上述核验才会采用；发表尚未核实不代表未发表。${num(v.withdrawn||0)} 项纳入研究已在 arXiv 撤回（依据 arXiv 自身记录核对），仍保留在列表中并标注撤回说明。署名单位逐字取自 ${num(v.full_texts_read)} 篇全文与官方目录，再与 ROR 机构登记匹配；不推断作者现任单位或所在地。`)}</p></section>
<section class="panel section"><h2>${t('Open-source discovery','开源仓库发现')}</h2><p>${t(`${num(os.candidates)} GitHub repositories were collected from ${num(os.search_queries)} topic and keyword searches, ${num(os.awesome_lists)} curated lists and paper links; ${num(os.reviewed)} were reviewed, ${num(os.included)} are listed and ${num(os.excluded)} were excluded with a recorded reason.`,`从 ${num(os.search_queries)} 组主题与关键词检索、${num(os.awesome_lists)} 个精选清单及论文链接中收集了 ${num(os.candidates)} 个 GitHub 仓库；其中 ${num(os.reviewed)} 个经过审核，${num(os.included)} 个被收录，${num(os.excluded)} 个因记录在案的理由被排除。`)} <button class="textlink" data-view="oss">${t('Selection criteria','收录标准')} →</button></p></section>
<section class="panel section"><h2>${t('Known gaps','已知缺口')}</h2><ul class="gaps"><li>${t(`${num(fin.boundary||0)} candidates remain boundary cases: no readable full text, or still ambiguous after reading it.`,`${num(fin.boundary||0)} 项候选仍为边界待定：无法读取全文，或读完全文仍难以判断。`)}</li><li>${t(`Formal publication is unverified for ${num(unverified)} included works. Not finding a publication does not prove there is none.`,`${num(unverified)} 项纳入研究的正式发表尚未核实。未找到发表记录不代表没有发表。`)}</li><li>${t(`${num(noAff)} included works have no affiliation evidence, mostly because the publisher does not list author institutions.`,`${num(noAff)} 项纳入研究缺少署名证据，多数是因为出版方未公开作者单位。`)}</li><li>${t('OpenReview and DBLP sit behind anti-bot checks and ACM Digital Library pages behind bot protection; we do not bypass them, so some full texts (TMLR, ACM venues) could not be read.','OpenReview、DBLP 设有反爬验证，ACM 数字图书馆页面有机器人防护；我们不绕过这些限制，因此部分全文（TMLR、ACM 会议）无法读取。')}</li><li>${t('The arXiv bulk harvest covers computer science; papers listed only in other categories (for example eess or math) are reached through keyword search alone.','arXiv 全量获取仅覆盖计算机科学类；只挂在其他类别（如 eess、math）的论文只能通过关键词检索找到。')}</li><li>${t('Scientific results are not independently reproduced.','论文中的科学结论未经独立复现。')}</li></ul></section>
${versionEvents()}<section class="panel section"><h2>${t('Download the data','下载数据')}</h2>${downloadsOpen?'':`<p class="muted">${t('Bulk downloads open once the terms of every data source are confirmed (see the snapshot page). Every paper, route and number stays browsable on this site.','批量下载将在各数据来源的条款确认后开放（见“冻结快照”页）。所有论文、航线和数字仍可在本站浏览。')}</p>`}${downloadsOpen?`<p><a class="btn" href="./data/research-records.json" download>${t('Research, resources, teams & events JSON','研究、资源、团队与事件 JSON')} ↓</a> <a class="btn" href="./data/pipeline-summary.json" download>${t('Source summary JSON','来源摘要 JSON')} ↓</a> <a class="textlink" href="./data/publication-records.json" download>${t('Publication evidence JSON','发表证据 JSON')} ↓</a> <a class="textlink" href="./data/discovery-index.csv" download>${t('Earlier discovery candidates CSV','早期发现候选 CSV')} ↓</a> <a class="textlink" href="./data/coverage-ledger.json" download>${t('Coverage ledger JSON','覆盖台账 JSON')} ↓</a></p><p class="muted">${t('Canonical exports keep English metadata and original source titles; Chinese display text is an editorial aid.','标准导出保留英文元数据与原始标题；中文展示文字仅用于辅助阅读。')}</p>`:''}</section>`}

