async function renderHomeView(){
 const token=++homeToken;
 $('#content').innerHTML='<p class="muted" role="status">'+t('Preparing the universe…','正在准备宇宙…')+'</p>';
 try{
  const homeModule=await import('./home.js'),skyModule=await import('./home-sky.js');
  const [H]=await Promise.all([fetch('./data/page-home.json').then(r=>r.json()),skyModule.loadSky()]);
  if(state.view!=='home'||token!==homeToken)return;
  const lctx={t,state,data,topicName,translated,openPaper,writeHash,setView,render:()=>{}};
  // the sky, the routes and the findings are computed over works not withdrawn on arXiv (withdrawn works stay listed, flagged)
  const cats=taxonomy.categories.filter(c=>!c.other),counts={works:H.works,clusters:cats.reduce((a,c)=>a+c.topics.length,0),galaxies:cats.length};
  const themes=cats.map(c=>({en:c.en,color:c.color}));
  $('#content').innerHTML=homeModule.renderHome({t,H:{...H,...(state.lang==='zh'?H.zh:H.en)},hero:homeModule.renderHero({t,counts,themes,galaxyName:c=>translated(c.en)})});
  const byId=new Map(data.papers.map(p=>[p.id,p]));
  skyModule.mountSky($('.hs'),{t,esc:escape,topicName,openPaper,titleOf:id=>byId.get(id)?.title,openCluster:name=>go({tag:name}),openTheme:id=>go({cat:id})});
  // the resource check opens in place under the mechanism it tests (navigation test, bands, new stars)
  const evBox=$('[data-home-ev-box]'),showEv=q=>{const ectx={...lctx,render:()=>showEv(q)};evBox.innerHTML=lensModule.renderEvidence(ectx,q);evBox.hidden=false;evBox.dataset.q=q;lensModule.bindLenses(ectx,evBox.querySelector('.fd'))};
  for(const b of document.querySelectorAll('[data-home-ev]'))b.onclick=()=>{const q=b.dataset.homeEv,open=!evBox.hidden&&evBox.dataset.q===q;for(const x of document.querySelectorAll('[data-home-ev]'))x.setAttribute('aria-expanded','false');if(open){evBox.hidden=true;evBox.dataset.q='';return}showEv(q);b.setAttribute('aria-expanded','true');evBox.scrollIntoView({behavior:smooth(),block:'nearest'})};
  for(const b of document.querySelectorAll('[data-home-goto]'))b.onclick=()=>{const [lens,qid]=b.dataset.homeGoto.split(':');state.lens=lens;setView('discover');const want='q-'+qid,t0=performance.now(),seek=()=>{const el=document.getElementById(want);if(el)el.scrollIntoView({block:'start'});else if(performance.now()-t0<4000)requestAnimationFrame(seek)};requestAnimationFrame(seek)};
  $('.hs-down')?.addEventListener('click',e=>{e.preventDefault();$('#home-lenses')?.scrollIntoView({behavior:smooth(),block:'start'})});
 }catch(e){console.error(e);if(state.view==='home'&&token===homeToken){$('#content').innerHTML='<div class="empty"><strong>'+t('The universe could not be loaded','宇宙页加载失败')+'</strong><button class="btn" id="home-retry">'+t('Retry','重试')+'</button></div>';$('#home-retry').onclick=renderHomeView}}
}
