let analysisModule=null;
// Explore: one page, five sections (map, cross-tab, over time, venues and code, institutions), with a sticky index
const exSections=()=>[['overview',t('Landscape','研究全景'),''],['map',t('Map','地图'),t('Where the work comes from and how that changes. Drag the time slider or press play, filter by cluster or role, shade by works, share or institutions, zoom into dense regions; click a country for its institutions and an institution for its papers. Below the map: a searchable directory of every institution.','研究从哪里来、怎样变化。拖动时间条或点播放，按星团或角色筛选，按工作数、份额或机构数着色，可放大密集地区；点国家看机构，点机构看论文。地图下方是可搜索的全部机构名录。')],
 ['cross',t('Cross-tab','交叉统计'),t('Any two dimensions against each other, including the model labels; the cells that stand out are listed beside the table.','任选两个维度交叉统计，包括模型标签；明显偏离的单元格列在表旁。')],
 ['time',t('Over time','时间趋势'),t('Which clusters gain or lose attention, year by year; volume and theme shares by period are under Findings › Research evolution.','哪些星团在逐年升温或降温；各时期的数量与主题份额见“发现 › 研究演化”。')],
 ['venues',t('Venues & forms','发表与形式'),t('Where the work is published and in which forms; released code is counted under Resources.','研究发表在哪里、以什么形式；论文公开代码的统计见“资源”。')],
];
function instRows(q=''){const inc=new Set(included().map(p=>p.id)),rows=data.teams.map(x=>[x,x.papers.filter(id=>inc.has(id)).length]).filter(([,n])=>n).sort((a,b)=>b[1]-a[1]),ql=q.trim().toLowerCase(),hit=ql?rows.filter(([x])=>x.name.toLowerCase().includes(ql)):rows;return {total:rows.length,hit:hit.length,html:hit.slice(0,40).map(([x,n])=>`<tr><td><button class="textlink" data-team="${escape(x.id)}">${escape(x.name)}</button></td><td>${teamFlag(x)}${escape(x.locations[0]?.country||'—')}</td><td class="num">${num(n)}</td></tr>`).join('')}}
function instDirectory(){const r=instRows();return `<div class="panel ex-dir"><div class="ex-dir-head"><h3>${t('Institution directory','机构名录')} <small>${num(r.total)}</small></h3><input type="search" data-ex-dir placeholder="${t('Find an institution…','查找机构…')}" aria-label="${t('Find an institution','查找机构')}"></div><div class="tablewrap"><table class="coverage"><thead><tr><th>${t('Institution','机构')}</th><th>${t('Country / region','国家/地区')}</th><th class="num">${t('Works','研究')}</th></tr></thead><tbody data-ex-dir-rows>${r.html}</tbody></table></div><p class="muted" data-ex-dir-note>${t(`Top 40 of ${num(r.total)} by works; search to find any institution. Click one for its papers.`,`按研究数显示前 40 个，共 ${num(r.total)} 个；可搜索任一机构，点击查看其论文。`)}</p></div>`}
async function renderAnalysisView(){if(state.view!=='landscape')return;$('#content').innerHTML=`<p class="muted" role="status">${t('Loading the analysis…','正在加载分析…')}</p>`;try{analysisModule??=await import('./analysis.js');timeMapModule??=await import('./timemap.js');await Promise.all([loadFacets(),timeMapModule.loadTimeMap()]);if(state.view!=='landscape')return;const ctx={t,escape,state,data,taxonomy,included:()=>included().filter(p=>!p.attributes?.withdrawal),facetsReady,facetAudit,facetTitle,facetName,facetOptions,facetValues,FACET_KEYS,topicName,categoryName,translated,topicsOf,formOf,yearOf,num,option,writeHash,go,famOf,groupNames,countriesOf,countryName,hasCode,teamById,pipeline};
 const cards={cross:['cross'],time:['trends'],venues:['forms','venues']},secs=exSections();
 $('#content').innerHTML=`<nav class="ex-toc" aria-label="${t('On this page','本页目录')}">${[secs[1],secs[0],...secs.slice(2)].map(([id,l])=>`<button data-ex-jump="${id}">${l}</button>`).join('')}</nav>${['map','overview',...secs.map(x=>x[0]).filter(x=>!['map','overview'].includes(x))].map(id=>secs.find(x=>x[0]===id)).map(([id,l,d])=>`<section class="ex-sec" id="ex-${id}">${id==='overview'?landscape('explore'):`<div class="ex-head"><h2>${l}</h2><p>${d}</p></div>${id==='map'?'<div id="tm-root"></div>'+instDirectory():analysisModule.renderSection(ctx,cards[id])}`}</section>`).join('')}${analysisModule.analysisNotes(ctx)}`;
 analysisModule.bindAnalysis(ctx);
 const tctx={t,state,data,taxonomy,topicName,translated,openPaper,writeHash,render:()=>{const el=$('#tm-root');if(!el||state.view!=='landscape')return;el.innerHTML=timeMapModule.renderTimeMap(tctx);timeMapModule.bindTimeMap(tctx)}};tctx.render();
 if(state.exJump){const j=state.exJump;state.exJump='';requestAnimationFrame(()=>$('#ex-'+j)?.scrollIntoView({block:'start'}))}
}catch(e){console.error(e);$('#content').innerHTML=`<div class="empty"><strong>${t('The analysis could not be loaded','分析加载失败')}</strong></div>`}}
// Papers: the collection the whole site is built on. Directory of clusters (the topic guides) -> a cluster page (its guide,
// then its papers) or the full list when searching or filtering
let papersToken=0;
function papersStrip(){const h=pipeline?.headline,rel=updates?.releases?.[0],inc=included(),wd=inc.filter(p=>p.attributes?.withdrawal).length;return `<section class="pp-strip"><div class="pp-strip-num"><b>${num(inc.length)}</b><span>${t('included works','项纳入研究')}</span></div><p>${wd?t(`${num(wd)} of them were withdrawn on arXiv and stay listed with a flag; the star map, findings and statistics use the other ${num(inc.length-wd)}. `,`其中 ${num(wd)} 项已在 arXiv 撤回，仍保留并标注；星图、观察与统计使用其余 ${num(inc.length-wd)} 项。`):''}${t('5,378 works first published through 30 September 2026 form the frozen field map; 404 later works are listed but are not in the map or the field statistics.','截至 2026 年 9 月 30 日首次公开的 5,378 篇构成冻结的领域地图；之后发表的 404 篇在此列出，但不进入地图与领域统计。')}</p><div class="pp-links"><a href="#method">${t('Method and data','方法与数据')} →</a>${downloadsOpen?`<a href="./data/research-records.csv" download>${t('Download CSV','下载 CSV')} ↓</a>`:''}</div></section>`}
function roleChips(){if(!facetsReady())return '';const cur=(state.facet||'').split(',').find(x=>x.startsWith('role:'))?.slice(5)||'';return `<div class="pp-roles" role="group" aria-label="${facetTitle(t,'role')}"><span>${facetTitle(t,'role')}</span>${['',...facetOptions('role')].map(o=>`<button data-pp-role="${o}" class="${o===cur?'is-on':''}" aria-pressed="${o===cur}">${o?facetName(t,'role',o):t('All','全部')}</button>`).join('')}</div>`}
async function renderPapersView(){const token=++papersToken;try{topicsModule??=await import('./topic-guides.js');await Promise.all([topicsModule.loadTopics(state.lang),loadFacets()])}catch(e){console.error(e)}if(state.view!=='papers'||token!==papersToken)return;
 const guides=topicsModule?.guideList?.()||[],bySlug=new Map(guides.map(g=>[g.slug,g])),byTopic=new Map(guides.map(g=>[g.topic,g]));
 let g=bySlug.get(state.guideSlug);if(!g&&state.tag&&byTopic.has(state.tag))g=byTopic.get(state.tag);
 if(g){state.guideSlug=g.slug;state.tag=g.topic;state.cat=''}else state.guideSlug='';
 const listMode=!g||!!(state.plist||state.query||state.cat||state.tag||state.team||state.year||state.venue||state.group||state.track||state.publication||state.form||state.country||state.art||state.rel||state.facet||state.pending);
 const tf=$('#toolbar-filters');if(tf)tf.innerHTML=activeFilters();
 const gctx={t,state,data,topicName,categoryName,external,openPaper,go,writeHash,render:()=>{if(state.view==='papers')renderPapersView()}};
 const list=()=>`${roleChips()}${researchList(filtered())}`;
 if(g&&topicsModule){$('#content').innerHTML=`${topicsModule.renderTopics(gctx)}<section class="pp-cluster-list" id="pp-list"><h2>${t(`All papers in ${topicName(g.topic)}`,`“${topicName(g.topic)}”的全部论文`)}</h2>${list()}</section>`;topicsModule.bindTopics(gctx)}
 else if(listMode||!topicsModule){$('#content').innerHTML=`${papersStrip()}${list()}`}
 else{$('#content').innerHTML=`${papersStrip()}${topicsModule.renderTopics(gctx)}<section class="pp-all"><button class="btn" data-pp-all>${t(`Browse all ${num(included().length)} papers`,`浏览全部 ${num(included().length)} 篇论文`)} →</button></section>`;topicsModule.bindTopics(gctx)}
 writeHash();summaryResizeObserver?.disconnect();summaryResizeObserver?.observe($('#content'));scheduleSummaryControls()}

// ---------- updates: latest-update panel (landscape) and the update history page ----------
function fmtDate(iso,opts){if(!iso)return '';const d=new Date(iso+'T12:00:00+08:00');return new Intl.DateTimeFormat(state.lang==='zh'?'zh-CN':'en-GB',Object.assign({day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Singapore'},opts||{})).format(d)}
function nextRun(){const sc=updates?.schedule;if(!sc)return null;const [hh,mm]=sc.time.split(':').map(Number),days=sc.days.map(d=>['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].indexOf(d)),now=Date.now();for(let i=0;i<9;i++){const loc=new Date(now+8*3600e3+i*864e5),run=Date.UTC(loc.getUTCFullYear(),loc.getUTCMonth(),loc.getUTCDate(),hh,mm)-8*3600e3;if(days.includes(loc.getUTCDay())&&run>now)return new Date(run)}return null}
function nextRunLabel(){const n=nextRun();return n?new Intl.DateTimeFormat(state.lang==='zh'?'zh-CN':'en-GB',{weekday:'short',day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Singapore'}).format(n)+(state.lang==='zh'?'（新加坡时间）':' SGT'):''}
function deltaItems(r){return [[r.papersAdded,t('papers added','篇论文新增'),true],[r.publicationsVerified,t('publications verified','项正式发表已核实')],[r.affiliationsAdded,t('papers gained affiliations','篇论文补充了署名机构')],[r.institutionsAdded,t('new institutions','个新机构')],[r.resourcesAdded,t('new artifacts','项新配套资源')],[r.topicsAdded,t('topic labels added','项主题标注新增')],[r.withdrawalsFlagged,t('withdrawals flagged','项撤回已标注')]].filter(([n,,keep])=>n||keep)}
function spark(rows){const pts=[{label:t('Baseline','初始'),date:'',total:updates.baseline?.papers||0},...rows.slice().reverse().map(r=>({label:r.release,date:r.date,total:r.totals.papers,add:r.papersAdded}))],max=Math.max(...pts.map(p=>p.total)),n=pts.length,x=i=>n>1?i/(n-1)*100:50,y=v=>100-v/max*100;
 return `<div class="latest-spark"><div class="latest-spark-title">${t('Included papers after each update','每次更新后的纳入论文数')}</div><div class="spark-plot"><svg viewBox="0 0 100 100" preserveAspectRatio="none" aria-hidden="true"><path class="spark-area" d="M0 100 ${pts.map((p,i)=>`L${x(i).toFixed(2)} ${y(p.total).toFixed(2)}`).join(' ')} L100 100Z"/><path class="spark-line" d="${pts.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(2)} ${y(p.total).toFixed(2)}`).join(' ')}"/></svg>${pts.map((p,i)=>`<span class="spark-pt${i===n-1?' last':''}" style="left:${x(i).toFixed(2)}%;top:${y(p.total).toFixed(2)}%" title="${escape(`${p.label}${p.date?' · '+fmtDate(p.date):''}: ${num(p.total)}${p.add?` (+${num(p.add)})`:''}`)}"></span>`).join('')}<b class="spark-last" style="top:${y(pts[n-1].total).toFixed(2)}%">${num(pts[n-1].total)}</b></div><div class="spark-axis"><span>${t('Baseline','初始')}</span><span>${escape(pts[n-1].label)}</span></div></div>`}
function latestPanel(){const r=updates.releases?.[0];if(!r)return '';const chk=updates.checks?.[0],newer=chk&&chk.date>r.date;const ps=(r.newPaperIds||[]).map(id=>data.papers.find(p=>p.id===id)).filter(Boolean).slice(0,4);
 return `<section class="latest" aria-labelledby="latest-title"><div class="latest-main"><div class="latest-head"><span class="latest-pulse" aria-hidden="true"></span><div><div class="latest-eyebrow">${t('LATEST UPDATE','最近一次更新')} · ${escape(r.release)}</div><h2 id="latest-title">${fmtDate(r.date)}</h2></div><div class="latest-next">${t('Next scheduled update','下次定时更新')}<b>${nextRunLabel()}</b></div></div>${r.note?`<p class="latest-note">${escape(translated(r.note))}</p>`:''}${newer?`<p class="latest-check">${t(`Last checked ${fmtDate(chk.date)}: no new records passed screening.`,`最近检查 ${fmtDate(chk.date)}：没有新记录通过筛选。`)}</p>`:''}
 <div class="latest-deltas">${deltaItems(r).map(([n,label,main])=>`<div class="delta${main?' main':''}"><strong>${n?'+':''}${num(n)}</strong><span>${label}</span></div>`).join('')}</div>
 ${ps.length?`<div class="latest-new"><h3>${t('New in this update','本次新增')}</h3><ul>${ps.map(p=>`<li><button data-paper="${escape(p.id)}">${escape(p.title)}</button><small>${escape(yearOf(p)||'')} · ${escape(pubName(p))}</small></li>`).join('')}</ul></div>`:''}
 <div class="latest-actions">${r.papersAdded?`<button class="btn" data-rel="${escape(r.release)}">${t(`View the ${num(r.papersAdded)} new papers`,`查看 ${num(r.papersAdded)} 篇新增论文`)} →</button>`:''}<button class="textlink" data-view="updates">${t('Update history','更新记录')} →</button></div></div>${spark(updates.releases)}</section>`}
// the observation report is an analysis version with its own, monthly clock (platform/release_analysis.py)
function analysisPanel(){const v=analyses?.versions||[],cur=v[0],now=data?.meta?.researchRelease;if(!cur)return '';
 return `<section class="panel section upd-analysis"><div class="eyebrow">${t('ANALYSIS VERSIONS','分析版本')}</div><h2>${t('Analysis: monthly, published after review','分析：每月一次，复核后发布')}</h2>
 <p class="muted">${t('Two clocks. Data releases (above and below) add papers, routes and resources twice a week, and every data count follows them. The analysis of the data — the findings on Discover, the numbers in the home page’s reading guide and the snapshot package — is a separate version: a candidate is computed from the latest data once a month, archived with its inputs and a change report, and replaces the version on the site only after review.','两种时钟。数据版本（本页下方）每周两次增加论文、航线和资源，所有数据计数随之更新。对数据的分析——“观察”与“追问”页的结论、首页“怎样读这片宇宙”里的数字和冻结快照——是单独的分析版本：每月用最新数据算出一个候选版本，连同输入文件和变化报告一起存档，复核后才替换网站上的版本。')}</p>
 <p class="upd-analysis-now">${t(`On the site: analysis <b>${escape(cur.analysisVersion)}</b>, computed on data release ${escape(cur.baseRelease)} (works through ${escape(cur.dataCutoff||'')}), published ${escape(cur.publishedOn||'')}.`,`当前网站：分析版本 <b>${escape(cur.analysisVersion)}</b>，基于数据版本 ${escape(cur.baseRelease)}（工作截至 ${escape(cur.dataCutoff||'')}），${escape(cur.publishedOn||'')} 发布。`)}${now&&now!==cur.baseRelease?t(` Data is now at ${escape(now)}.`,` 数据现已更新到 ${escape(now)}。`):''}</p>
 <table class="upd-analysis-table"><thead><tr><th>${t('Version','版本')}</th><th>${t('Data release','数据版本')}</th><th>${t('Works through','工作截至')}</th><th>${t('Published','发布')}</th><th>${t('Note','说明')}</th></tr></thead><tbody>${v.map(x=>`<tr><td><b>${escape(x.analysisVersion)}</b></td><td>${escape(x.baseRelease)}</td><td>${escape(x.dataCutoff||'')}</td><td>${escape(x.publishedOn||'')}</td><td>${escape(x.note||'')}</td></tr>`).join('')}</tbody></table></section>`}
function updatesView(){if(!updates)return '';const rows=updates.releases||[],b=updates.baseline;
 const steps=[t('New arXiv computer-science records since the last run and new official conference records are matched against the agent-safety terms, then screened (DeepSeek first pass, Claude Opus review; boundary cases resolved from the full text).','自上次运行以来新增的 arXiv 计算机科学记录与官方会议记录先按 Agent 安全术语匹配，再经筛选（DeepSeek 初筛、Claude Opus 复核；边界候选依据全文判定）。'),
  t('New inclusions get affiliations (matched to ROR), their own code and data links, publication status and paper form; earlier works are re-checked for new formal publications and arXiv withdrawals.','新纳入的论文补充署名机构（匹配 ROR）、自有代码与数据链接、发表状态和论文形式；已有论文重新检查是否有新的正式发表或 arXiv 撤回。'),
  t('The open-source landscape adds new repositories (search and the new papers’ own code) and refreshes GitHub metrics; new works join the star map with their labels and brightness bands; every data figure is recomputed, validated and published.','开源全景补充新仓库（检索及新论文自有代码）并刷新 GitHub 指标；新论文带着标签和亮度波段进入星图；所有数据数字重新计算、校验后发布。')];
 const card=(r,i)=>`<article class="upd" style="--i:${i}"><div class="upd-date"><strong>${fmtDate(r.date,{year:undefined})}</strong><span>${escape((r.date||'').slice(0,4))}</span></div><div class="upd-body"><div class="upd-head"><span class="upd-rel">${escape(r.release)}</span>${r.run?.kind==='scheduled'?`<span class="upd-kind">${t('Scheduled','定时')}</span>`:''}${r.note?`<p>${escape(translated(r.note))}</p>`:''}</div><div class="upd-deltas">${deltaItems(r).map(([n,label,main])=>`<span class="${main?'main':''}${n?'':' zero'}"><b>${n?'+':''}${num(n)}</b> ${label}</span>`).join('')}</div><div class="upd-foot"><span>${t('After this update','更新后')}: ${num(r.totals.papers)} ${t('papers','篇论文')} · ${num(r.totals.institutions)} ${t('institutions','个机构')} · ${num(r.totals.countries)} ${t('countries and regions','个国家和地区')}</span>${r.papersAdded?`<button class="textlink" data-rel="${escape(r.release)}">${t('View papers added','查看新增论文')} →</button>`:''}</div></div></article>`;
 return `<section class="panel section upd-intro"><div class="upd-sched"><div><div class="eyebrow">${t('SCHEDULE','更新计划')}</div><h2>${t('Data: every Monday and Thursday, 02:30 Singapore time','数据：每周一、周四 02:30（新加坡时间）')}</h2><p class="muted">${t('Next run','下次运行')}: <b>${nextRunLabel()}</b></p></div>${spark(rows)}</div><ol class="upd-steps">${steps.map(x=>`<li>${x}</li>`).join('')}</ol><p class="muted">${t('Scope decisions that remain open after the full-text review go to the project owner and are published once decided. Figures below are read from each release’s record of changes, not typed in.','全文判定后仍无法决定的范围问题交由项目负责人判定，确定后再发布。下列数字取自每次发布的变更记录，而非手工填写。')}</p></section>
 ${analysisPanel()}
 <div class="upd-list">${rows.map(card).join('')}${b?`<article class="upd baseline"><div class="upd-date"><strong>${t('Baseline','初始')}</strong><span>${t('before R053','R053 之前')}</span></div><div class="upd-body"><div class="upd-head"><p>${t('The curated collection the updates build on.','后续更新所基于的人工整理收录。')}</p></div><div class="upd-foot"><span>${num(b.papers)} ${t('papers','篇论文')} · ${num(b.institutions)} ${t('institutions','个机构')} · ${num(b.countries)} ${t('countries and regions','个国家和地区')}</span></div></div></article>`:''}</div>`}
const PAPER_VIEWS=['evolution','foundations','opportunities','evidence','method','versions'],OLD_VIEWS={versions:'method',rq1:'evolution',rq2:'foundations',rq3:'opportunities',questions:'foundations',synthesis:'opportunities',rq:'evidence',notes:'method',insights:'method',snapshot:'versions',coverage:'versions',updates:'versions',teams:'landscape',topics:'papers'};
let paperModule=null,paperToken=0;
async function renderPaperView(v){const token=++paperToken;$('#content').innerHTML=`<p class="muted" role="status">${t('Loading…','正在加载…')}</p>`;try{paperModule??=await import('./paper.js');await paperModule.loadPaper(v);if(state.view!==v||token!==paperToken)return;const ctx={t,state,data,openPaper,topicName,translated,setView,go,lang:state.lang};$('#content').innerHTML=paperModule.renderPaper(v,ctx);paperModule.bindPaper(v,ctx);}catch(e){console.error(e);if(state.view===v)$('#content').innerHTML=`<div class="empty"><strong>${t('This page could not be loaded.','页面加载失败。')}</strong></div>`}}
function renderContent(){if(OLD_VIEWS[state.view]){state.view=OLD_VIEWS[state.view];writeHash()}if(PAPER_VIEWS.includes(state.view))return renderPaperView(state.view);if(state.facet&&!facetsReady()){loadFacets().then(()=>renderContent());return}if(!summariesReady&&['papers','research'].includes(state.view))loadSummaries().then(ok=>{if(ok&&['papers','research'].includes(state.view))renderContent()});const papers=filtered(),v=state.view;const tf=$('#toolbar-filters');if(tf)tf.innerHTML=activeFilters();if(v==='explore')return renderPathsView();if(v==='topics')return renderTopicsView();if(v==='home')return renderHomeView();if(v==='discover'||v==='findings')return renderLensView('discover');if(v==='questions')return renderLensView('questions');if(v==='synthesis')return renderLensView('synthesis');if(v==='rq')return renderRqView();if(v==='notes')return renderLensView('notes');if(v==='method')return renderLensView('method');if(v==='insights')return renderInsightsView();if(v==='snapshot')return renderSnapshotView();if(v==='oss')return renderOssView();if(v==='papers')return renderPapersView();if(v==='landscape')return renderAnalysisView();$('#content').innerHTML=v==='papers'?researchList(papers):v==='research'?research(papers):v==='resources'?resources(papers):v==='teams'?teams(papers):v==='updates'?updatesView():coverage();summaryResizeObserver?.disconnect();if(v==='research'||v==='papers'){summaryResizeObserver?.observe($('#content'));scheduleSummaryControls()}}
function authorVersionNotes(p){const rows=p.publicationVersions.flatMap(v=>(v.authorVersionObservations||[]).filter(o=>JSON.stringify(o.authors)!==JSON.stringify(v.authors)));const unique=[...new Map(rows.map(o=>[o.evidence_url+'|'+o.authors.join('|'),o])).values()];return unique.length?`<h3>${t('Version-specific author names','各版本作者署名')}</h3>${unique.map(o=>`<div class="evidence">${external(o.evidence_url,t('Manuscript / project author list','稿件／项目页作者列表'))}<p>${o.authors.map(escape).join(' · ')}</p></div>`).join('')}<p class="muted">${t('Each list preserves its source spelling and order. Name differences do not resolve unique person identities.','各列表保留来源中的拼写和顺序。姓名差异不用于直接判定独立研究者身份。')}</p>`:''}
function benchmarkProfiles(p){return (p.attributes.benchmark_profiles||[]).map(b=>`<section class="benchmark-profile"><h3>${t('Benchmark data profile','基准数据档案')} · ${escape(b.name)}</h3><p class="muted">${t('Resource checked','资源核查日期')}: ${escape(b.observed_on)} · ${t('Revision','版本')}: <code>${escape(b.revision)}</code></p><div class="tablewrap"><table class="coverage"><thead><tr><th>${t('Measure','指标')}</th><th>${t('Count and unit','数量与单位')}</th><th>${t('Evidence','证据')}</th></tr></thead><tbody>${b.metrics.map(m=>`<tr><td>${escape(translated(m.label))}</td><td>${escape(m.value)} ${escape(translated(m.unit))}</td><td>${external(m.sourceUrl,m.basis==='file_count'?t('Counted from file','文件计数'):t('Publisher reported','出版方报告'))}</td></tr>`).join('')}</tbody></table></div>${[['splitNote',t('Data organization','数据组织方式')],['evaluation',t('Evaluation conditions','评测条件')],['licenseNote',t('Reuse terms','复用条款')],['limits',t('Version and verification limits','版本与核验限制')]].map(([key,label])=>`<p><strong>${label}:</strong> ${escape(translated(b[key]))}</p>`).join('')}<details><summary>${t('Audited primary sources','核查的原始来源')}</summary>${b.sources.map(s=>`<div class="evidence">${external(s.evidence_url,s.evidence_url.replace(/^https:\/\//,''))}<small>SHA-256: ${escape(s.sha256)}</small></div>`).join('')}</details></section>`).join('')}
const detailShards=new Map();
async function loadDetail(p){if(p.d===undefined||p._detail)return;if(!detailShards.has(p.d))detailShards.set(p.d,fetch(`./data/details/${p.d}.json`).then(r=>{if(!r.ok)throw Error('detail');return r.json()}));const rec=(await detailShards.get(p.d))[p.id];if(rec){Object.assign(p,rec.paper);p._teamEvidence=rec.teamEvidence;p._detail=true}}
function showDetail(){const d=$('#detail');if(!d.open)d.showModal();d.scrollTop=0}
async function openPaper(id){const p=data.papers.find(x=>x.id===id);if(!p)return;state.detail=id;try{await loadDetail(p)}catch{detailShards.delete(p.d);$('#detail .detail').innerHTML=`<p>${t('Details could not be loaded. Check your connection and try again.','详情加载失败，请检查网络后重试。')}</p>`;showDetail();return}const rs=data.resources.filter(r=>(r.workIds||[r.workId]).includes(p.workId));$('#detail .detail').innerHTML=`<span class="overline">${escape(pubName(p))}</span><h2>${escape(p.title)}</h2><p class="authors">${p.authors.map(escape).join(' · ')}</p><div class="tags">${topicsOf(p).map(topicChip).join('')}${extraTags(p).map(x=>chip(translated(x))).join('')}</div><h3>${p.attributes.summary_basis==='original_abstract'?(p.attributes.abstract_display_extent==='excerpt'?t('Original abstract excerpt','原文摘要节选'):t('Original abstract','原文摘要')):t('Research summary','研究概述')}</h3><p>${text(p,'summary')}</p>${p.attributes.summary_basis==='original_abstract'?`<p class="muted">${p.attributes.abstract_display_extent==='excerpt'?t('Excerpt · follow the source for the complete abstract','节选 · 完整摘要请见原文链接'):t('Author abstract · original language','作者原文摘要 · 保留原语言')} · ${external(p.attributes.original_abstract_source?.url||p.url,t('Abstract source','摘要来源'))}${p.attributes.original_abstract_source?.version?' · '+escape(p.attributes.original_abstract_source.version):''}${p.attributes.original_abstract_source?.license_url?' · '+external(p.attributes.original_abstract_source.license_url,t('Reuse license','复用许可')):''}${p.attributes.abstract_display_extent==='full'?'<br>'+escape((p.attributes.original_abstract_source?.authors||p.authors).join(' · ')):''}</p>`:''}${p.attributes.curation_status==='basic_record_enrichment_pending'?`<p class="muted">${t('Scope screening complete. Detailed methods, resource verification, affiliations and version links are queued for enrichment.','范围筛查已完成。详细方法、资源核验、机构署名和版本关联正在分批补充。')}</p>`:''}${p.attributes.withdrawal?`<div class="withdrawn-note"><strong>${t('Withdrawn on arXiv','已在 arXiv 撤回')} · ${escape(p.attributes.withdrawal.version)}, ${escape(p.attributes.withdrawal.date)}</strong><p>${t('Notice on the arXiv record','arXiv 记录中的撤回说明')}: “${escape(p.attributes.withdrawal.notice)}”</p><p class="muted">${t('The record and its scope decision are kept for history; the results of earlier versions should not be treated as valid evidence.','保留此记录及其范围判定以备查；早期版本的结论不应视为有效证据。')} ${external(p.attributes.withdrawal.url,t('arXiv record','arXiv 记录'))}</p></div>`:''}<h3>${t('Connection to agent safety','与 Agent Safety 的关联')}</h3><p>${text(p,'scope')}</p><p class="hint">${text(p,'statusNote')}</p>${p.attributes.scope_limits?`<h3>${t('Scope limits','适用边界')}</h3><p>${escape(translated(typeof p.attributes.scope_limits==='string'?p.attributes.scope_limits:JSON.stringify(p.attributes.scope_limits)))}</p>`:''}
${p.publication.paperGenre==='position_paper'?`<p class="hint">${t('Position paper: arguments and proposals; not enacted requirements.','立场论文：观点和建议，不代表已生效的要求。')}</p>`:''}<h3>${t('Publication and version history','发表与版本记录')}</h3>${p.publicationVersions.length?p.publicationVersions.map(v=>`<div class="evidence">${external(v.url,`${v.venueName} ${v.year||''} · ${trackName(v.track)}${v.status==='accepted'?' · '+t('Accepted','已录用'):''}`)}<small>${v.status==='accepted'?t('Official program page date','官方会议页面日期'):t('Source-reported publication date','来源报告的发表日期')}: ${escape(v.date||t('Unknown','未知'))} · ${t('Official title and authors matched','已匹配官方标题与作者')}</small>${v.doi?`<small>DOI: ${escape(v.doi)}</small>`:''}</div>`).join(''):`<p class="muted">${t('Formal publication remains unverified. Reported venue:','正式发表情况待核实。原记录报告的会议：')} ${escape(p.venueReported)}</p>`}${authorVersionNotes(p)}${p.attributes.release_metadata_review==='R052'&&p.publication.status==='unverified'&&(p.attributes.publication_author_reports||[]).some(x=>/accepted|published|ICML|ICLR|NeurIPS|ACL|AAMAS|AAAI|EMNLP|TMLR|FAccT|SaTML/i.test(x))?`<details><summary>${t('Author-reported venue information · not yet verified','作者报告的发表信息 · 尚未独立核实')}</summary><p>${(p.attributes.publication_author_reports||[]).filter(x=>/accepted|published|ICML|ICLR|NeurIPS|ACL|AAMAS|AAAI|EMNLP|TMLR|FAccT|SaTML/i.test(x)).map(escape).join('<br>')}</p></details>`:''}<p>${t('First recorded date','首次记录日期')}: ${escape(p.firstRecordedDate||t('Unknown','未知'))}${p.preprintUrl?' · '+external(p.preprintUrl,t('arXiv versions','arXiv 版本')):''}</p><p class="muted">${t('The summary and safety evidence retain their cited source version. Linking a formal publication does not establish that every experiment is unchanged.','概述和安全证据保留其引用版本。关联正式发表页面不代表所有实验在版本间完全一致。')}</p>
${p.teams.length?`<h3>${t('Affiliated research bodies','署名研究机构')}</h3>${p.teams.map(id=>{const x=data.teams.find(x=>x.id===id),e=(x.evidence||[]).find(e=>e.recordId===p.id)||p._teamEvidence?.[id];return `<div class="evidence"><strong>${teamFlag(x)}${escape(x.name)}</strong>${e?` · ${external(e.url,t('Affiliation evidence','署名证据'))}<small>${escape(translated(e.qualifier))}</small>`:''}</div>`}).join('')}`:''}
${!p.teams.length&&p.attributes.release_metadata_review==='R052'?`<p class="muted">${t('Affiliation sources checked; no unambiguous paper-time institution is recorded yet.','已检查署名来源，目前尚无可明确登记的论文发表时机构。')}</p>`:''}${benchmarkProfiles(p)}<h3>${t('Associated resources','关联资源')}</h3>${rs.length?rs.map(r=>`<div class="evidence">${external(r.url,r.title)}<small>${typeName(r.kind)} · ${escape(r.license||t('License unverified','许可证待核实'))}</small></div>`).join(''):`<p class="muted">${t('No verified companion resource is recorded yet; the authors may still have released one.','尚未记录经过核实的配套资源；不代表作者没有发布。')}</p>`}${(p.attributes.resource_availability_notes||[]).map(n=>`<p class="muted">${escape(translated(n.note))} ${external(n.source.url,t('Availability statement','资源说明'))}</p>`).join('')}<h3>${t('Primary evidence','原始证据')}</h3>${p.evidence.slice(0,4).map(e=>`<div class="evidence">${external(e.evidence_url,t('Open primary source','打开原始来源'))}<small>${escape(translated(e.locator||''))}</small>${e.supports?`<p>${escape(translated(e.supports))}</p>`:''}</div>`).join('')}${external(p.url,t('Read the paper','阅读论文'),'btn')}`;showDetail()}
const HASH_KEYS={lens:'lens',fq:'findingsQ',pl:'plist',tmm:'tmMonth',tmw:'tmWindow',tmc:'tmCluster',tmr:'tmRole',tmf:'tmFocus',tmx:'tmMeasure',tmd:'tmDots',msn:'msN',msf:'msFrom',msk:'msKinds',fc:'findingsCluster',fl:'findingsLayer',sband:'skyBand',stopic:'skyTopic',sthread:'skyThread',spaper:'skyPaper',dbasis:'pathDateBasis',yfrom:'pathYearFrom',yto:'pathYearTo',udate:'pathUnknownDate',setting:'pathSetting',pform:'pathForm',pcode:'pathCode',pstatus:'pathPubStatus',include:'pathInclude',exclude:'pathExclude',cond:'pathCondition',ca:'pathConnectA',cb:'pathConnectB',ckind:'pathConnectKind',chops:'pathConnectHops',cscope:'pathConnectScope',cpath:'pathConnectSelected',pview:'pathView',prole:'pathRole',seeds:'pathSeeds',rpage:'pathResultsPage',pp:'pathProfile',pw:'pathWeights',idea:'pathQuery',path:'pathRoute',ptab:'pathTab',paper:'pathPaper',layout:'pathMode',edges:'pathLayer',edge:'pathEdge',plimit:'pathLimit',guide:'guideSlug',gtab:'guideTab',gw:'guideMonths',io:'insightOpportunity',it:'insightTab',iw:'insightMonths',ia:'insightAsOf',ic:'insightTopic',ip:'insightPreset',iweights:'insightWeights',iq:'insightQuery',ipage:'insightPage',irs:'insightRepoSort',rel:'rel',fa:'facet',form:'form',ctry:'country',art:'art',q:'query',topic:'tag',cat:'cat',team:'team',year:'year',venue:'venue',group:'group',track:'track',pub:'publication',g:'ossGroup',tab:'ossTab',rtype:'ossType',rtopic:'ossTopic',lic:'ossLicense',rsort:'ossSort',rpaper:'ossPaper',rq:'ossQuery',ch:'ossChart',an:'anChart',ab:'anBy',am:'anMode',at:'anTheme',ax:'anAxis',av:'anVenueMode',ar:'anRow',aco:'anCol',axm:'anXmode',anm:'anNorm',at2:'anTheme2',af:'anFrom',ato:'anTo',al:'anLayout',atv:'anTview',alt:'anLineTheme',alm:'anLmeasure'};
const ALIASES={timemap:['landscape','map'],teams:['landscape','people'],topics:['papers','']};
function parseHash(){state.guideEvidence='';state.guideEvidenceLimit=12;const [raw,qs]=location.hash.slice(1).split('?'),p=new URLSearchParams(qs||''),view=ALIASES[raw]?.[0]||raw;if(ALIASES[raw])state.exJump=ALIASES[raw][1];state.view=views()[view]?view:homeView();for(const [k,key] of Object.entries(HASH_KEYS))state[key]=p.get(k)||'';state.pending=p.get('pending')==='1';state.page=Math.max(1,parseInt(p.get('page'),10)||1);state.size=SIZES.includes(+p.get('size'))?+p.get('size'):50;state.sort=['oldest','title'].includes(p.get('sort'))?p.get('sort'):'newest';state.metric=p.get('metric')==='papers'?'papers':'teams';if(['discover','findings'].includes(state.view)&&state.lens==='questions'){state.view='questions';state.lens=''}}
function writeHash(){const p=new URLSearchParams();for(const [k,key] of Object.entries(HASH_KEYS))if(state[key]&&(!['lens','fq'].includes(k)||['discover','findings'].includes(state.view)))p.set(k,state[key]);if(state.pending)p.set('pending','1');if(state.page>1)p.set('page',state.page);if(state.size!==50)p.set('size',state.size);if(state.sort!=='newest')p.set('sort',state.sort);const qs=p.toString();history.replaceState(null,'','#'+state.view+(qs?'?'+qs:''))}
function syncToolbar(){const set=(id,v)=>{const el=$('#'+id);if(el&&el.value!==v)el.value=v};set('form',state.form);set('search',state.query);set('topic',state.cat?'cat:'+state.cat:state.tag);for(const id of ['year','group','venue','track','publication'])set(id,state[id]);if($('#pending'))$('#pending').checked=state.pending}
const smooth=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';
function changed(scrollToResults=false){state.page=1;writeHash();syncToolbar();renderContent();if(scrollToResults&&state.view==='landscape')$('#results')?.scrollIntoView({block:'start',behavior:smooth()})}
function setView(view){if(ALIASES[view]){state.exJump=ALIASES[view][1];view=ALIASES[view][0]}if(!views()[view])return;const moved=view!==state.view;if(moved)state.page=1;state.view=view;writeHash();shell();if(moved)window.scrollTo({top:0,behavior:'instant'})}
function bind(){ $('.toolbar')?.addEventListener('submit',e=>e.preventDefault());$('#search')?.addEventListener('input',e=>{state.query=e.target.value;state.page=1;writeHash();renderContent()});$('#topic')?.addEventListener('change',e=>{const v=e.target.value;if(v.startsWith('cat:')){state.cat=v.slice(4);state.tag=''}else{state.tag=v;state.cat=''}changed()});for(const id of ['year','venue','track','publication','form'])$('#'+id)?.addEventListener('change',e=>{state[id]=e.target.value;changed()});$('#group')?.addEventListener('change',e=>{state.group=e.target.value;state.venue='';state.page=1;writeHash();shell()});$('#pending')?.addEventListener('change',e=>{state.pending=e.target.checked;changed()});$('#theme').onclick=()=>{const next=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=next;try{localStorage.setItem('atlas-theme',next)}catch{}shell()};$('#language').onclick=async()=>{state.lang=state.lang==='en'?'zh':'en';try{localStorage.setItem('atlas-language',state.lang)}catch{}if(state.lang==='zh')await ensureTranslations();shell()};$('#detail .close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()})}
function resetFilters(){Object.assign(state,{plist:'',guideSlug:'',query:'',facet:'',tag:'',cat:'',team:'',year:'',venue:'',group:'',track:'',publication:'',form:'',country:'',art:'',rel:'',pending:false,page:1})}
function go(f){resetFilters();Object.assign(state,f);state.view='papers';writeHash();shell();requestAnimationFrame(()=>$('#results')?.scrollIntoView({block:'start',behavior:smooth()}))}
document.addEventListener('click',e=>{const b=e.target.closest('[data-ex-inst],[data-ex-jump],[data-pp-role],[data-pp-all],[data-view],[data-paper],[data-tag],[data-topic],[data-cat],[data-clear],[data-page],[data-metric],[data-zoom],[data-cluster],[data-close-panel],[data-to-landscape],[data-team],[data-year],[data-reset],[data-abstract],[data-rel]');if(!b||b.disabled)return;e.preventDefault();const d=b.dataset;
 if(d.exInst){state.anTheme2=d.exInst;state.exJump='people';writeHash();renderContent();return}
 if(d.exJump){$('#ex-'+d.exJump)?.scrollIntoView({block:'start',behavior:smooth()});return}
 if(d.ppRole!==undefined){const rest=(state.facet||'').split(',').filter(x=>x&&!x.startsWith('role:'));state.facet=[...rest,...(d.ppRole?['role:'+d.ppRole]:[])].join(',');state.page=1;writeHash();renderContent();return}
 if(b.hasAttribute('data-pp-all')){state.plist='1';state.page=1;writeHash();renderContent();return}
 if(d.abstract)toggleAbstract(b);  else if(d.rel)go({rel:d.rel});
 else if(d.view)setView(d.view);
 else if(d.paper)openPaper(d.paper);
 else if(d.topic!==undefined){state.tag=state.tag===d.topic?'':d.topic;state.cat='';changed(!!state.tag)}
 else if(d.tag!==undefined){if($('#detail').open)$('#detail').close();state.tag=d.tag;state.cat='';state.page=1;if(['papers','research'].includes(state.view))changed(true);else setView('papers')}
 else if(d.catView){state.cat=d.cat;state.tag='';setView(d.catView)}
 else if(d.cat!==undefined){state.cat=state.cat===d.cat?'':d.cat;state.tag='';changed(!!state.cat)}
 else if(d.clear){if(d.clear==='pending')state.pending=false;else state[d.clear]='';if(d.clear==='group')state.venue='';if(d.clear==='group'){state.page=1;writeHash();shell()}else changed()}
 else if(d.page){state.page=+d.page;writeHash();renderContent();$('#results')?.scrollIntoView({block:'start',behavior:smooth()})}
 else if(d.metric){state.metric=d.metric;writeHash();for(const x of document.querySelectorAll('[data-metric]'))x.setAttribute('aria-pressed',String(x.dataset.metric===state.metric));$('#map-panel').hidden=true;drawMap()}
 else if(d.zoom){$('#map-panel').hidden=true;if(d.zoom==='reset'){Object.assign(mapView,{k:1,x:0,y:0});drawMap()}else zoomMap(d.zoom==='in'?2:.5)}
 else if(d.cluster!==undefined)openCluster(+d.cluster);
 else if(b.hasAttribute('data-close-panel'))$('#map-panel').hidden=true;
 else if(b.hasAttribute('data-to-landscape'))$('#landscape-title')?.scrollIntoView({block:'start',behavior:smooth()});
 else if(d.team){resetFilters();state.team=d.team;setView('papers');window.scrollTo({top:0,behavior:'instant'})}
 else if(d.year){resetFilters();state.year=d.year;setView('papers')}
 else if(b.hasAttribute('data-reset')){resetFilters();writeHash();shell()}});
document.addEventListener('input',e=>{if(!e.target.matches('[data-ex-dir]'))return;const r=instRows(e.target.value),rows=$('[data-ex-dir-rows]'),note=$('[data-ex-dir-note]');if(rows)rows.innerHTML=r.html;if(note)note.textContent=t(`${num(r.hit)} matching institutions${r.hit>40?'; showing 40':''}.`,`匹配 ${num(r.hit)} 个机构${r.hit>40?'，显示前 40 个':''}。`)});
