try{const [a,l,z,x,o,ps,bd,up,dl,an]=await Promise.all([fetch('./data/atlas.json'),fetch('./data/land.json'),state.lang==='zh'?fetch('./data/translations.zh.json'):null,fetch('./data/topic-taxonomy.json').catch(()=>null),fetch('./data/oss.json',{method:'HEAD'}).catch(()=>null),fetch('./data/pipeline-summary.json').catch(()=>null),fetch('./data/borders.json').catch(()=>null),null,null,null]);analyses=an?.ok?await an.json().catch(()=>null):null;ossAvailable=!!o?.ok;downloadsOpen=!!dl?.ok&&!/text\/html/.test(dl.headers.get('content-type')||'')/* a missing file falls back to the HTML page on Pages */;pipeline=ps?.ok?await ps.json().catch(()=>null):null;borders=bd?.ok?await bd.json().catch(()=>null):null;updates=up?.ok?await up.json().catch(()=>null):null;if(!a.ok||(z&&!z.ok))throw Error('data');data=await a.json();translations=z?await z.json():{};land=l.ok?await l.json():null;taxonomy=x?.ok?await x.json().catch(()=>null):null;teamById=new Map(data.teams.map(x=>[x.id,x]));resourceById=new Map(data.resources.map(x=>[x.id,x]));parseHash();if(location.hash&&!location.hash.startsWith('#'+state.view))writeHash();shell();const later=()=>loadSummaries().then(ok=>{if(ok&&state.query)renderContent()});'requestIdleCallback' in window?requestIdleCallback(later,{timeout:4000}):setTimeout(later,2500)}catch{$('#app').innerHTML=`<main class="error"><h1>${t('Research data could not be loaded','研究数据加载失败')}</h1><p>${t('Check your connection and refresh. Data is bundled with the atlas.','请检查网络并刷新。研究数据随网站一同提供。')}</p><button class="btn" id="retry">${t('Retry','重试')}</button></main>`;$('#retry').onclick=()=>location.reload()}
